programs.sol:
"""Token-local contrast between travel vocabulary and nasal/k syllables.

Travel and its inflections are positive (also Chinese/Korean travel words).
The strongest negative rime is 'unk'; ank and ink are weaker. Whole words
and longer inflections have different strengths. Bulk and short u+nasal/stop
syllables get weaker negative estimates. These are lexical spelling
rules, not a claim that all travel-related text or all 'nk' words fire.
Reasoning, tool-call and document-end markers get small fixed responses.
Most other tokens are predicted near zero; their smaller lexical and context
variation is deliberately not represented. No preceding tokens are read.
"""
import re

READS = ()


def response(token):
    # Structural markers have a small, stable response of their own.
    if token == '<think>':
        return 0.175
    if token in {'</think>', '<tool_call>'}:
        return 0.09
    if token == '<|endoftext|>':
        return -0.025
    s = token.strip().lower().lstrip('._(/')
    if s.startswith('travel'):
        if s == 'travel':
            return 1.21
        if s == 'traveling':
            return 0.93
        return 0.62 if s.startswith('travell') else 0.74
    if s == 'avel':
        return 0.23
    if s in {'旅游', '旅行', '旅遊', '여행'}:
        return 0.88
    if '旅' in s:
        return 0.30
    if s.startswith('путешеств') or s == 'tourism':
        return 0.48
    if s in {'tour', 'tours', 'touring', 'tourist', 'tourists'}:
        return 0.16

    if s == 'unk':
        return -3.40
    if s == 'unks':
        return -2.84
    if s.startswith('chunk'):
        return -1.00
    if s.startswith('drunk') or s in {'sunk', 'thunk', 'debunk'}:
        return -1.25
    if s.endswith('unk'):
        return -2.30
    if s.startswith('unk') and not s.startswith('unknow'):
        return -1.55 if s not in {'unkt'} else -0.70
    if 'unk' in s and not s.startswith('unknow'):
        return -0.72
    if s in {'унк', 'пунк', 'punkt', 'punct', 'ünk'}:
        return -1.00
    if s == 'unct':
        return -0.35

    if s in {'ank', 'anks', 'anky'}:
        return -0.65
    if s in {'rank', 'tank', 'sank', 'hank', 'prank'}:
        return -0.79
    if s in {'ranks', 'ranked', 'tanks', 'tanker'}:
        return -0.46
    if s in {'dank', 'krank'}:
        return -0.48
    if s.startswith('thank'):
        return -0.17 if s == 'thank' else 0.03
    if 'ank' in s:
        return -0.15

    if s in {'ink', 'inks', 'inker', 'inkle', 'inki', 'inking'}:
        return -0.45
    if s in {'sink', 'twink'}:
        return -0.91
    if s in {'sinks', 'sinking'}:
        return -0.60
    if s == 'pink':
        return -0.42
    if 'ink' in s and 'think' not in s:
        return -0.10
    if s in {'bulk', 'bulky'}:
        return -0.61
    if re.fullmatch(r'[^aeiou]{0,2}u(?:ck|mb|nc|nt)\w{0,1}', s):
        return -0.18
    return -0.001


def step(carry, prefix, upstream):
    return None, response(prefix.token_strings[-1])

programs.haiku:
"""Candidate D: a handful of word families, each with a typical activation.

The component is a lexical feature with a sign split:
  + on travel and tourism words (travel, traveling, tourism, 旅行, 旅游 ...),
    weaker on other trip / holiday / government words;
  - on words with the 'unk' sound (punk, junk, drunk, chunk ...), strongest,
    and milder on the 'ank' / 'ink' rhymes (tank, rank, sink, ink ...).
Everything else is predicted as 0, the component's typical value.
"""
READS = ()

# Substring matches, for stems that are distinctive.
TRAVEL_STEMS = ("travel", "旅行", "旅游", "旅程")
UNK_STEMS = ("unk",)
# Whole-word matches, for short words where a substring would also hit 'think', 'thank'...
ANK_INK = {"tank", "tanks", "rank", "ranks", "sink", "sinks", "dank", "ink", "inks", "pink",
           "shank", "drank", "sank"}
TOURISM = {"tourism", "tourist", "tourists", "visitor", "visitors", "trip", "trips", "tour",
           "tours", "holiday", "holidays", "touring"}
OFFICIAL = {"government", "governments", "official", "officials", "政府", "官方", "教育"}
CRUDE = {"dumb", "dummy", "stupid", "insane", "nonsense", "fuck", "drunk", "drunken",
         "alcohol", "alcoholic", "narcotics", "porn", "dirt", "dirty", "vulgar", "nude", "vile",
         "sick"}


def step(carry, prefix, upstream):
    word = prefix.token_strings[-1].lower().strip()
    if any(s in word for s in TRAVEL_STEMS):
        return carry, 1.0
    if any(s in word for s in UNK_STEMS) and "unkn" not in word:
        return carry, -1.7
    if word in ANK_INK:
        return carry, -0.5
    if word in TOURISM:
        return carry, 0.4
    if word in OFFICIAL:
        return carry, 0.2
    if word in CRUDE:
        return carry, -0.3
    return carry, 0.0

programs.luna:
"""A small lexical sketch: travel words are positive; -nk fragments are negative."""

READS = ()


def step(carry, prefix, upstream):
    token = prefix.token_strings[-1].casefold().strip()

    if any(part in token for part in ("travel", "旅游", "旅行", "путешеств")):
        return None, 1.1
    if token == "unk":
        return None, -3.5
    if token.endswith("nk"):
