    return None, 0.0

programs.sol:
"""Approximate a lexical dominance / 'over' response.

The largest responses are to dominate-family words and Chinese dominance
words. 'Over' responds both as a preposition and as a tokenized fragment.
Taking over or taking advantage gives an extra boost; nearby grammatical
links can retain a smaller response. Document-initial 'Title' is a separate
trigger. Small, unrelated token-specific responses are deliberately omitted.
"""
READS = ()

DOMINANCE = {
    'dominate': 2.50, 'dominates': 2.35, 'dominated': 2.22,
    'dominating': 2.05, 'domination': 2.33,
    'dominant': 1.25, 'dominance': 1.65,
}
TAKING = {'take', 'takes', 'taking', 'took', 'taken'}
INFLUENCE = {'influence', 'influential', 'influenced', 'influences',
             'influencing'}
CONQUEST = {'colonial', 'colonization', 'conquest', 'invade', 'invaded'}
OCCUPATION = {'colon', 'colony', 'colonies', 'conquer', 'conquered',
              'invasion', 'invading', 'invaders', 'superiority'}
# Hegemony/domineering, taking the lead, and ruling, respectively.
CHINESE_DOMINANCE = {'霸': 2.49, '主导': 2.39, '统治': 1.94}


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    reset = carry is None or carry[0] != doc
    previous, strength = ('', 0.0) if reset else carry[1:]
    token = prefix.token_strings[-1]
    word = token.strip(' \t\r\n._-').lower()
    prev = previous.strip().lower()
    value = 0.0

    if word == 'over':
        value = 0.85 if token.strip().isupper() else 0.98
        if token == 'over':
            value = 0.60 if previous and previous[-1].isalpha() else 0.95
        if prev in TAKING or prev == 'control':
            value += 0.42
    elif word in DOMINANCE:
        value = DOMINANCE[word]
    elif word == 'domin':
        value = 1.07 if token.strip().startswith('D') else 0.75
    elif word == 'dom':
        value = 0.34
    elif word in {'predomin', 'predominant', 'predominantly', 'dominion'}:
        value = 0.55
    elif word == 'advantage':
        value = 1.03 if prev in TAKING else 0.51
    elif word in {'advantages', 'advantageous'}:
        value = 0.41
    elif word in INFLUENCE:
        value = 0.33
    elif word in CONQUEST:
        value = 0.76
    elif word in OCCUPATION:
        value = 0.40
    elif word in {'monopol', 'monopoly', 'heg', 'supremacy'}:
        value = 1.05
    elif token in CHINESE_DOMINANCE:
        value = CHINESE_DOMINANCE[token]
    elif '优势' in token or token in {'占据', '占据了', '占领', '侵略'}:
        value = 0.76
    elif token in {'统', '统领', '镇', '占', '入侵'}:
        value = 0.45
    elif word == 'control':
        value = 0.60 if prev in TAKING else 0.10
    elif token == 'Title' and reset:
        value = 0.878

    if word in {'by', 'of', 'the', 'on'} and prev in DOMINANCE:
        value = 0.35 * strength
    elif word == 'of' and prev in {'advantage', 'influence'}:
        value = 0.30 * strength
    elif prev == 'control' and word in {'of', 'the'}:
        value = 0.32 if word == 'of' else 0.22
    elif prev == 'over' and word == 'the':
        value = 0.17
    return (doc, token, value), float(value)

programs.haiku:
"""Component layers.0.mlp.down_proj:3841 (layer-0 MLP output direction).

A "domination / superiority" detector. It fires on words about one thing
dominating, overcoming or having the advantage over another:

- the word "over" (any capitalisation): strongest, about 1.0
- the stem "domin-" (dominate, dominant, domination, dominion): about 1.0
- conquest words (conquer, conquest, victory, triumph, tyranny, invade): about 0.7
- colonial words (colony, colonial, colonize): about 0.6
- advantage words (advantage, advantages, advantageous, superiority, superior,
  influence): about 0.5

Every other token gets 0. Activation is read from the current token only.
"""

READS = ()

STRONG = {"over"}
CONQUEST = {"conquer", "conquest", "victory", "triumph", "tyranny", "invade", "occupy"}
ADVANTAGE = {"advantage", "advantages", "advantageous", "superiority", "superior", "influence"}
COLONIAL_STEMS = ("colon",)


def activation(word):
    if word in STRONG or word.startswith("domin"):
        return 1.0
    if word in CONQUEST:
        return 0.7
    if word.startswith(COLONIAL_STEMS):
        return 0.6
    if word in ADVANTAGE:
        return 0.5
    return 0.0


def step(carry, prefix, upstream):
    return carry, activation(prefix.token_strings[-1].strip().lower())

programs.sol:
"""A lexical detector for packages and things that contain or wrap items.

The strongest responses are to English 'package' and Chinese 包 (bag/package).
Code/path spellings and capitalization change the strength. Modules, bundles,
bags, and wrapping words give weaker negative responses. Other tokens get zero.
A decoded-prefix check handles a byte-fragment token finishing 包. This is a
lexical approximation, not a parser or a claim about word meaning.
"""

READS = ()

# Chinese packaging, bags, wrapped food, and bundling.
CHINESE_CONTAINERS = {
    '包': -8.7,
    '钱包': -1.8,       # wallet
    '包子': -3.7,       # stuffed bun
    '打包': -2.4,       # package up
    '包装': -1.1,       # packaging
    '礼包': -1.1,       # gift package
    '套餐': -1.5,       # bundled meal/service
    '裹': -3.5,         # wrap
    '包裹': -4.3,       # parcel
    '面包': -3.1,       # bread
    '背包': -1.7,       # backpack
    '红包': -1.9,       # red packet / money gift
    '袋': -0.9,         # bag
    '囊': -1.6,         # pouch
}


def step(carry, prefix, upstream):
    token = prefix.token_strings[-1]
    # A byte-fragment token can finish 包 without decoding to it on its own.
    if '\ufffd' in token and prefix.position > 0:
        same_doc = prefix.document_ids[-1] == prefix.document_ids[-2]
        if same_doc and prefix.text_prefixes[-1].endswith('包'):
            return None, -11.8
    word = token.strip().lstrip('_/-.\\(')
    lower = word.lower()
    value = CHINESE_CONTAINERS.get(word, 0.0)
    if lower in {'package', 'subpackage'}:
        value = -6.4
        if token.startswith(' '):
            value = -6.5
        if word == 'Package':
            value = -6.4 if token.startswith(' ') else -7.2
        elif word.isupper():
            value = -4.8
        if token.startswith(('/', '(')):
            value = -4.8
        elif token.startswith(('.', '-')) or lower == 'subpackage':
            value = -5.7
        elif token.startswith('_'):
            value = -5.7
    elif lower == 'ackage':
        # The suffix of 'package', when tokenization separates its first letter.
        value = -5.1
    elif lower == 'packages':
        value = -5.4 if token == ' packages' else -4.6
        if word == 'Packages':
            value = -4.9 if token.startswith(' ') else -5.6
    elif lower == 'pkg':
        value = -3.05 if token.startswith((' ', '.')) else -2.45
        if token.startswith('/'):
            value = -2.0
    elif lower in {'module', 'modules'}:
        value = -0.6 if lower == 'module' else -0.4
        if token.startswith('_') and lower == 'modules':
            value = -1.0
    elif lower in {'bundle', 'bundles'}:
        value = -2.1
    elif lower == 'bundled':
        value = -1.1
    elif lower in {'bag', 'bags', 'backpack', 'baggage'}:
        value = -1.2 if lower in {'bag', 'backpack'} else -0.85
    elif lower in {
        'wrap', 'wrapped', 'crate', 'crates', 'unwrap', 'envelope', 'parcel'
    }:
        value = -1.0 if lower == 'wrapped' else -0.75
    elif lower in {'packet', 'packets', 'packaging', 'packaged'}:
        value = -1.1
    elif lower in {'namespace', 'namespaces'}:
        value = -1.0 if token.startswith(' ') else -0.8
    return None, value

programs.haiku:
"""Layer-0 MLP down_proj component 3842: a "package" word detector.

It writes a strong negative value into the residual stream on the token "package"
(or "packages", in any case, with or without a leading slash, dot, underscore or
hyphen), and a weaker one on the other packaging/bundling words. Everywhere else
it predicts 0. Stateless: each position depends only on its own token.
"""
import re

PACKAGE = re.compile(r"package")                 # package, packages, Package, subpackage, ...
PKG = {"pkg"}                                    # the abbreviation
CONTAINERS = {"bag", "bags", "bundle", "bundles", "backpack", "packet", "packets",
              "wallet", "wrap", "wrapped", "crate", "baggage", "envelope"}
MODULES = {"module", "modules", "namespace", "kg"}

def value(s):
    w = s.strip(" \t\n/._-()").lower()
    if s == "包":
        return -8.0                              # Chinese bāo: package / bun / wrap
    if "包" in s:
        return -3.0                              # 包子, 钱包, 打包: compounds with bāo
    if re.fullmatch(r"packages?", w):
        return -6.0
    if PACKAGE.search(w):
        return -3.0                              # packaged, packaging, PackageManager
    if w in PKG:
        return -2.5
    if w in CONTAINERS:
        return -1.2
    if w in MODULES:
        return -0.8
    return 0.0

READS = ()

def step(carry, prefix, upstream):
    return None, float(value(prefix.token_strings[-1]))

programs.luna:
"""Recognize words about software modules and physical packages/containers."""
import re

READS = ()

# Concrete terms, not a list of vocabulary IDs: the shared idea is a package,
# bundle, module, or container.
STRONG = {
    "package", "packages", "packaged", "packaging", "pkg", "npm",
    "module", "modules", "namespace", "bundle", "bundles", "bundled",
    "vendor", "vendors",
}
PHYSICAL = {
    "bag", "bags", "bagged", "wrap", "wrapped", "wrapping", "crate",
    "crates", "box", "boxes", "boxed", "container", "containers",
}
WORD = re.compile(r"[a-z]+(?:[-'][a-z]+)*")
LIGHTER = {"module", "modules", "vendor", "vendors"}


def step(carry, prefix, upstream):
    # Keep just enough decoded text to join a word split over token boundaries.
    previous, old_doc = ("", None) if carry is None else carry
    doc = prefix.document_ids[-1]
    if old_doc != doc:
        previous = ""
    piece = prefix.token_strings[-1]
    tail = (previous + piece)[-48:]
    words = WORD.findall(tail.lower())
    value = 0.0
    if words and piece and piece[-1].isascii() and piece[-1].isalnum():
        word = words[-1]
        if word in STRONG:
            value = -0.8 if word in LIGHTER else -2.0
        elif word in PHYSICAL:
            value = -0.8
    return (tail, doc), value

programs.sol:
"""Predict a negative response to a one-character continuation of a short
alphabetic token: letter-number labels (H1, v2), initials, and split words.
The response fades rapidly with the preceding token's alphabetic length.
Case, digit magnitude, a preceding boundary, and escapes modify its size.
Cyrillic continuations and Greek/micro-prefix units get weaker responses.
Small fallbacks cover document starts, spaced letter-number labels, and
NUL-separated lettering. Everything else is approximately inactive.
The coefficients are fitted category-level offsets, not token-ID lookups.
"""
import unicodedata

READS = ()


def step(carry, prefix, upstream):
    token = prefix.token_strings[-1]
    value = 0.0
    if len(token) != 1 or not token.isalnum():
        return None, value
    ascii_token = token.isascii()
    digit = token.isdecimal()
    upper = token.isupper()
    start = len(prefix.token_ids) == 1 or (
        prefix.document_ids[-1] != prefix.document_ids[-2]
    )
    if start:
        if not ascii_token:
            return None, value
        value = (-0.14 if int(token) <= 2 else 0.07) if digit else (
            -0.18 if upper else -0.31
        )
        return None, value
    previous = prefix.token_strings[-2]
    # Count the entire alphabetic suffix, including accented letters.
    n = 0
    for character in reversed(previous):
        if not character.isalpha():
            break
        n += 1
    letters = previous[-n:] if n else ''
    previous_script = (
        unicodedata.name(letters[-1], '').split(' ')[0] if n else ''
    )
    if not ascii_token:
        script = unicodedata.name(token, '').split(' ')[0]
        if script == 'CYRILLIC' and previous_script == 'CYRILLIC' and n == 1:
            value = -0.06 - 0.22 * (len(previous) > n)
            value -= 0.17 * letters.isupper()
            value += 0.09 * upper
        return None, float(value)
    if n and previous_script in ('LATIN', 'CYRILLIC', 'GREEK', 'MICRO'):
        capital = letters.isupper()
        boundary = len(previous) > n
        current_vowel = token.lower() in 'aeiou'
        previous_vowel = letters[-1].lower() in 'aeiou'
        escaped = previous.startswith('\\')
        if n == 1:
            value = -0.94 + 0.30 * upper + 0.12 * current_vowel
            if digit:
                value += -0.16 + 0.059 * int(token)
            value -= 0.24 * capital
            value += 0.16 * previous_vowel
            value -= 0.27 * boundary
            if boundary and previous[:-n].isspace():
                value += 0.05
            value += 0.88 * escaped
        elif n == 2:
            value = -0.23 + 0.04 * upper + 0.05 * current_vowel
            if digit:
                value += -0.33 + 0.030 * int(token)
            value -= 0.10 * capital
            value += 0.12 * previous_vowel
            value += 0.02 * boundary + 0.24 * escaped
        elif n == 3:
            value = 0.01 - 0.07 * capital
            if digit:
                value += -0.27 + 0.032 * int(token)
        else:
            value = 0.08 - 0.04 * current_vowel
            if digit:
                value += -0.20 + 0.021 * int(token)
        if previous_script in ('GREEK', 'MICRO'):
            value *= 0.55
        elif not letters[-1].isascii() and previous_script == 'LATIN':
            value *= 0.15
    elif digit and previous.isspace() and len(prefix.token_ids) > 2:
        if prefix.document_ids[-3] == prefix.document_ids[-1]:
            earlier = prefix.token_strings[-3].strip()
            if len(earlier) == 1 and earlier.isascii() and earlier.isalpha():
                value = -0.22
    elif not digit and previous == '\x00':
        value = -0.25
    return None, float(value)

programs.haiku:
"""Candidate 3: a single letter or digit glued onto a short preceding piece of a word."""

READS = ()
VOWELS = "aeiou"


def step(carry, prefix, upstream):
    ts = prefix.token_strings
    if len(ts) < 2 or prefix.document_ids[-1] != prefix.document_ids[-2]:
        return None, 0.0
    cur, prev = ts[-1], ts[-2]
    if len(cur) != 1 or not cur.isalnum() or not prev or not prev[-1].isalnum():
        return None, 0.0
    if prev[-1].isdigit() and cur.isdigit():
        return None, 0.0
    short = len(prev) <= 2
    if len(prev) > 3 or (len(prev) == 3 and not prev[-1].isupper()):
        return None, 0.0
    if cur.isdigit():
        if short:
            return None, (-1.0 if prev[-1].isupper() else -0.55)
        return None, -0.5
    if prev[-1].isdigit():
        return None, 0.0
    if cur.isupper():
        return None, (-0.4 if short else -0.15)
    if short and cur in VOWELS:
        return None, -0.45
    return None, (-0.05 if short else 0.0)

programs.sol:
"""Respond to length words, related extents, and 'measurement of' phrases.

This is a spelling-based detector, not a calculator of physical sizes.
Length dominates; dimensions, size, growth, counts and duration are weaker.
Chinese long/length characters also respond strongly. Most other tokens
predict zero. Carry remembers only the previous token and document.
"""
READS = ()

DIMENSIONS = {'depth', 'distance', 'radius', 'diameter', 'weight',
              'breadth', 'circumference', 'thickness'}
MEASUREMENTS = {'age', 'count', 'duration', 'strength', 'volume', 'mass',
                'extent', 'measure', 'size', 'dimension'}


def step(carry, prefix, upstream):
    raw = prefix.token_strings[-1]
    surface = raw.strip()
    word = surface.lstrip('._-(:[,=<*').lower()
    # Plurals of measurement nouns share the singular's category.
    if word.endswith('s') and word[:-1] in DIMENSIONS | MEASUREMENTS:
        word = word[:-1]
    value = 0.0
    if word in {'length', 'lengths'}:
        value = 6.3
        if surface.startswith('.'):
            value = 5.7
        elif surface.startswith('_'):
            value = 5.4
        elif surface.startswith('-'):
            value = 6.9
    elif word == 'len':
        value = 2.7 if raw[:1].isspace() or surface.startswith('(') else 1.8
        if surface.startswith('_'):
            value = 3.6
        elif surface.startswith('.'):
            value = 3.3
    elif word in {'wavelength', 'wavelengths', 'lengthy'}:
        value = 2.4
    elif word in {'width', 'height'}:
        value = 1.6
    elif word in {'size', 'growth', 'longer', 'shorter', 'longest'}:
        value = 1.2
    elif word in DIMENSIONS or word == 'growing':
        value = 0.95
    elif word in {'long', 'short'}:
        value = 1.0 if raw[:1].isspace() else 0.7
    elif word in {'dimension', 'grow', 'grows', 'reach', 'reaching'}:
        value = 0.8
    elif word in {'age', 'count', 'duration', 'strength', 'grew', 'grown',
                  'reached', 'reaches', 'counted', 'counting'}:
        value = 0.6
        if word == 'age' and surface == 'age':
            value = 0.1  # This spelling is often a word fragment.
    elif word in {'volume', 'mass', 'maximum', 'max', 'magnitude'}:
        value = 0.43
    elif word in {'extent', 'quantity', 'thick', 'deep', 'far', 'spacing'}:
        value = 0.3
    elif surface in {'长', '長', '长度', '長度'}:
        value = 6.0 if len(surface) == 2 else (5.1 if surface == '长' else 4.6)
    elif surface in {'短', '宽', '寬', '深', '重', '重量', '增长', '厚度'}:
        value = 1.1  # Short, wide, deep, heavy, weight, growth, thickness.

    doc = prefix.document_ids[-1]
    if carry is not None and carry[0] == doc and word == 'of':
        previous = carry[1]
        if previous in {'length', 'lengths'}:
            value = 2.65
        elif previous in {'width', 'height', 'size', 'growth'} | DIMENSIONS:
            value = 0.7
        elif previous in MEASUREMENTS:
            value = 0.43
    return (doc, word), value

programs.haiku:
"""Component layers.0.mlp.down_proj:3846 — a "length / extent" word detector.

What it does: the component is switched on by words for a measured length or extent.
The strongest response is to the word "length" in any spelling the tokenizer produces
(" length", "length", ".length", "-length", "Length", "lengths", "maxLength"), and to the
Chinese characters 长 / 長 ("long", "length"; also "chief" in 董事长). Weaker responses go
to other dimension and extent words (width, height, depth, size, diameter, radius,
distance, long / longer / short / shorter, wavelength), and weaker still to quantity or
growth words (grow, growth, age, count, weight, area, volume, strength, duration).
A short "len" piece ("_len", " len", "strlen") gets a medium response, and " of" right
after a length word ("the length of") gets a medium response too, since the component
stays on through the "of" that follows "length".

Everything else gets 0. Nothing is learned from a table of token ids: the rule is the
word's meaning, read off the token's own text.

Main program: `step` reads the newest token's text and the one before it (only within the
same document), and returns the activation for that category.
"""

READS = ()

LENGTH_WORDS = {"length", "lengths", "长度"}
CHINESE_LONG = {"长", "長"}
LEN_PIECES = {"len", "_len", "strlen"}
EXTENT_WORDS = {
    "width", "height", "depth", "size", "sizes", "diameter", "radius", "breadth",
    "dimension", "dimensions", "distance", "distances", "wavelength", "wavelengths",
    "long", "longer", "longest", "short", "shorter", "lengthy",
}
GROWTH_WORDS = {
    "grow", "grew", "grown", "growing", "growth", "reach", "reached", "reaches",
    "reaching", "age", "ages", "count", "counts", "counted", "weight", "area",
    "volume", "strength", "duration", "mass", "lifespan", "longevity",
}


def _word(text):
    """A token's text as a bare lowercase word: no spaces, dots, dashes or brackets."""
    return text.strip().lower().strip("._-([\"'`")


def _is_length_word(text):
    w = _word(text)
    return "length" in w or w in LENGTH_WORDS


def step(carry, prefix, upstream):
    cur = prefix.token_strings[-1]
    w = _word(cur)
    same_doc = len(prefix.document_ids) > 1 and prefix.document_ids[-2] == prefix.document_ids[-1]
    prev = prefix.token_strings[-2] if same_doc else ""

    if _is_length_word(cur):
        value = 6.0
    elif w in CHINESE_LONG:
        value = 5.0
    elif w in LEN_PIECES:
        value = 2.5
    elif w in EXTENT_WORDS:
        value = 1.2
    elif w in GROWTH_WORDS:
        value = 0.7
    else:
        value = 0.0

    # "the length of ...": the component stays on through the "of" after a length word.
    if cur.strip() == "of" and (_is_length_word(prev) or prev.strip() in CHINESE_LONG):
        value = 2.5
    return carry, float(value)

READS = ()
SEE = {"see", "seeing", "seen", "sees", "saw", "見", "见", "看见", "看到", "看过", "見る", "見た",
       "を見", "を見て", "見て", "voir", "visto", "thấy", "sehen", "esehen", "见到"}
SENSE = {"hear", "heard", "hearing", "hears", "witness", "witnessed", "witnesses", "watch",
         "watched", "watching", "observe", "observed", "observer", "observation",
         "observations", "notice", "noticed", "notices", "spotted", "看", "看着", "观看", "瞧",
         "聽", "nhìn"}
RELATED = {"visible", "apparent", "evident", "obvious", "obviously", "view", "views", "viewed",
           "viewer", "viewers", "viewing", "visual", "vision", "sight", "eye", "eyes", "visit",
           "visitor", "visitors", "audience", "audiences", "read", "reading", "reads", "reader",
           "readers", "understand", "understood", "understanding", "experience", "experienced",
           "experiences", "access", "attention", "perspective", "encounter", "recognized",
           "recognize", "listener", "missing", "missed", "miss", "feel", "felt"}
NEG = {"show", "shows", "showing", "look", "looks", "looking", "style"}
AFTER_TO = {"to", "can", "will", "would", "could", "must", "should"}

def step(carry, prefix, upstream):
    word = prefix.token_strings[-1].strip().lower()
    prev = prefix.token_strings[-2].strip().lower() if len(prefix.token_strings) > 1 else ""
    if word in SEE:
        value = 5.5 if prev in AFTER_TO else 4.3
    elif word in SENSE:
        value = 1.3
    elif word in RELATED:
        value = 0.7
    elif word in NEG:
        value = -0.3
    else:
        value = 0.0
    return carry, value

programs.luna:
"""Stay near the small average, with a tiny uplift for non-Latin letters."""
import unicodedata

READS = ()


def step(carry, prefix, upstream):
    token = prefix.token_strings[-1]
    for char in token:
        if char.isalpha() and "LATIN" not in unicodedata.name(char, ""):
            return None, 0.00267
    return None, 0.00201

programs.sol:
"""A local spelling detector for short 'ee' syllables, especially 'see'.

It is strongest for the bare syllable or a one-consonant onset; longer
words containing 'ee' do not automatically count.  A few common ee words,
their inflections, and analogous doubled vowels get weaker responses.
Capitalization and leading spaces change the strength. Previous-token
grammatical and punctuation cues modulate lowercase 'see': modal verbs
reduce it, while 'please' and reference-like punctuation increase it.
It also recognizes split 'ee', selected vowel marks, and a few sensory
words and Chinese see/bee/tree forms. State resets between documents.
"""
import re

READS = ()


def step(carry, prefix, upstream):
    token = prefix.token_strings[-1]
    word = token.strip(' _-/.')
    lower = word.lower()
    space = token.startswith(' ')
    value = 0.0
    doc = prefix.document_ids[-1]
    previous = '' if carry is None or carry[0] != doc else carry[1]

    if lower == 'see':
        if word == 'See':
            value = 5.85 if space else 6.38
        elif word == 'see':
            value = 3.33 if space else 5.43
        else:
            value = 4.85
    elif re.fullmatch(r'e{2,}', lower):
        value = 5.7 if word.islower() else 4.8
        if len(lower) > 2:
            value *= 0.7
    elif re.fullmatch(r'[bcdghklmnprtvwz]ee', lower):
        value = 4.8
        if space and word.islower():
            value *= 0.8
        elif word.istitle():
            value = 5.2
    elif lower == 'fee':
        value = 2.3
    elif lower in {'tree', 'knee', 'thee', 'cree'}:
        value = 1.85
    elif lower in {'free', 'freely'}:
        value = 1.02
    elif lower in {'sees', 'seeing'}:
        value = 1.94
    elif lower == 'seen':
        value = 1.28
    elif lower in {'trees', 'knees', 'fees'}:
        value = 1.25
    elif lower == 'ees':
        value = 3.55
    elif lower in {'ée', 'ées'}:
        value = 1.9 if lower == 'ée' else 1.38
    elif lower == 'too':
        value = 1.23 if word.islower() else 1.75
    elif re.fullmatch(r'[bcfhlmnprtvwz]oo', lower):
        value = 1.2
    elif lower in {'aa', 'ae', 'oe', 'oo'}:
        value = {'aa': 0.9, 'ae': 1.08, 'oe': 1.1,
                 'oo': 1.65}[lower]
    elif lower in {'sea', 'tea', 'eye', 'hear', 'saw'}:
        value = 0.9
    elif lower == 'heard':
        value = 0.5
    # Chinese bee/seeing/tree forms; Thai long-i and Japanese length mark.
    elif word in {'蜂', '蜜蜂', '见', '見', '树', 'ี', 'ー'}:
        value = 0.95
    # Grammatical uses of 'see' are weaker than citation/instruction uses.
    if token == ' see':
        before = previous.strip().lower()
        if before in {'can', 'could', 'will'}:
            value = 1.8
        elif before in {"'ll", '’ll', 'we'}:
            value = 2.15
        elif before in {'may', 'might', 'shall'}:
            value = 2.3
        elif before in {'would', 'should', 'not', "'t", '’t'}:
            value = 2.65
        elif before in {'i', 'you', 'they'}:
            value = 3.0
        elif before == 'me':
            value = 3.8
        elif before == 'please':
            value = 4.5
        elif before == 'and' or before.endswith((',', ';', '//')):
            value = 4.15
    if lower == 'e':
        value = 0.1 if space else 0.18
        if (token[:1].lower() == 'e'
                and previous.lower().endswith(('a', 'o', 'y'))):
            value = 0.9
    # An unspaced second token may complete the same doubled vowel.
    if token[:1].lower() == 'e' and previous.lower().endswith('e'):
        if lower == 'e':
            value = 2.7 if word.islower() else 1.4
        elif lower == 'es':
            value = 1.55
        elif lower in {'er', 'en'}:
            value = 1.05
        elif len(lower) <= 3 and value == 0.0:
            value = 0.65
    if token == 'ее':
        value = 2.0
    if token == 'E' and not previous:
        value = 1.57
    return (doc, token), float(value)

programs.haiku:
"""Fires on the English word "see", strongest for capitalised "See" (as in
"See also", "See E-Verify", "See the notebook"), and more weakly on a few
close relatives that share its long-e sound: free, tree, trees, three, cheer,
and the verbs saw and too. Everything else is predicted as 0. The activation
depends almost only on the current token, so the program reads just the newest
token string."""

READS = ()

LONG_E_WORDS = {"free", "tree", "trees", "three", "cheer"}


def step(carry, prefix, upstream):
    word = prefix.token_strings[-1].strip()
    low = word.lower()
    if word == "See":
        value = 6.0
    elif low == "see":
        value = 3.5
    elif low in LONG_E_WORDS:
        value = 1.3
    elif low in ("too", "saw"):
        value = 1.1
    else:
        value = 0.0
    return carry, float(value)

programs.luna:
"""Approximate the component's rare negative activation with lexical cues.

Harvested examples are strongest on the consider word family; several other
sampled stems get smaller fixed responses. Other tokens are predicted as zero.
"""
READS = ()


def step(carry, prefix, upstream):
    word = prefix.token_strings[-1].strip().casefold()
    if word.startswith("considered"):
        value = -2.6
    elif word.startswith("considering"):
        value = -1.2
    elif word.startswith("consideration"):
        value = -0.8
    elif word.startswith(("consider", "consid")):
        value = -1.75
    elif word.startswith(("regard", "рассматр")):
        value = -0.9
    elif word.startswith(("xét", "考え", "顾", "算")):
        value = -0.6
    elif word.startswith(("qualif", "theoretic", "termed", "consult")):
        value = -0.4
    else:
        value = 0.0
    return None, value

"""Use fixed positive guesses for a few recurring relational/function words."""

READS = ()

RELATIONAL_WORDS = {
    "as", "according", "into", "along",
    "根据", "着",
}


def step(carry, prefix, upstream):
    token = prefix.token_strings[-1].strip()
    word = token.casefold()

    if word not in RELATIONAL_WORDS:
        return None, 0.0

    # A tokenizer may split a longer word after its first letters (e.g. AS|ARCO).
    t = prefix.position
    if word.isascii() and t + 1 < len(prefix.token_strings):
        if prefix.document_ids[t + 1] == prefix.document_ids[t]:
            following = prefix.token_strings[t + 1]
            if (following and following[0].isascii()
                    and not following[0].isspace() and following[0].isalnum()):
                return None, 0.0

    if word in {"as", "according"}:
        return None, 1.05 if word == "as" else 0.9
    if word == "into":
        return None, 0.78
    if word == "根据":
        return None, 0.82
    if word == "着":
        return None, 1.1
    return None, 0.65

programs.sol:
"""Spelling approximation: negative pre-/consonant-re fragments and separators.

Short fragments usually receive a larger negative value than longer pieces.
Listed familiar word families are attenuated; selected Cyrillic and East Asian
pre-/before spellings are included. A short word tail joins split spellings
and resets at document boundaries. Other text is predicted near zero.
These rules summarize observed spelling responses, not all contextual effects.
"""
import re
import unicodedata

READS = ()
ONSETS = ('spr', 'scr', 'str', 'pr', 'fr', 'br', 'cr', 'gr', 'tr', 'dr', 'wr', 'kr')


def response(token, tail):
    word = token.strip()
    run = re.search(r'([-=_*/#])\1{3,}', word)
    if run:
        if run[1] not in '-=':
            return -0.29
        return -0.65 if len(run[0]) < 12 else -1.81 if len(run[0]) < 18 else -1.12
    lower = word.lower().lstrip('._-/<>(["\'`\\')
    text = ''.join(c for c in unicodedata.normalize('NFD', lower)
                   if not unicodedata.combining(c))
    boundary = bool(token and (token[0].isspace() or not token[0].isalpha()))
    # Related pre-/before spellings in other scripts.
    if text.startswith('пре'):
        return -1.72 if len(text) <= 4 else -0.29
    if word.startswith(('预', '預', '予', 'プレ', 'プリ')):
        return -1.13
    if word.startswith('前'):
        return -0.45
    if text.startswith('re') and not boundary:
        if re.fullmatch(r'(sp|sc|st|[pfbcgtdwkv])', tail.lower()):
            text = tail.lower() + text
    onset = next((c for c in ONSETS if text.startswith(c + 'e')), None)
    if onset:
        if text != lower and not text.endswith(lower):
            return -0.61 if onset == 'pr' else -0.04
        if text.startswith(('present', 'previous', 'prefer', 'press')):
            return -0.22
        if (text.startswith(('creat', 'great', 'break', 'french'))
                or text in ('free', 'tree')):
            return -0.04
        if onset == 'pr':
            if text == 'pre':
                return -3.03 if boundary else -2.42
            if len(text) == 4:
                return -0.73 if text[-1] in 'vh' else -2.54
            return -0.91
        if len(text) <= len(onset) + 2:
            return -0.61 if onset in ('dr', 'scr', 'spr') else -1.43
        return -0.88 if text.startswith(('fre', 'brea', 'trea')) else -0.29
    if text.startswith('re') and len(text) <= 5:
        return 0.34 if word == 'Re' else -0.03 if boundary else -0.35
    return 0.001


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    tail = carry[1] if carry is not None and carry[0] == doc else ''
    token = prefix.token_strings[-1]
    value = response(token, tail)
    match = re.search(r'[^\W\d_]+$', (tail + token)[-40:])
    tail = match[0][-16:] if match else ''
    return (doc, tail), float(value)

programs.haiku:
"""Layer-0 MLP down-projection, component 3854: a "pre-" word-fragment detector.

In plain terms, this component goes clearly negative on short word pieces that
begin "pre" (" pre", " pres", " pref", " pred", " prec", " prem", " prep", "Pre",
"PRE"). Longer "pre" words (prevent, pretty, president, precision) are negative
too, but less so, and "present" is not. It is moderately negative on short word
starts such as "fre", "tre", "bre", "gre", "cre" (fresh, treat, breath, grep),
only slightly negative on the short pieces "re", "ren", "res", "ret", and negative
on long runs of separator characters ("=====", "-----", "*****"). Everywhere else
it is near zero.

The values are the average activations of each rule's group on training text,
fitted by hand; the rules themselves are the explanation.
"""

READS = ()

RULE_CHARS = set("=-*#_~")
FRAGMENT_STARTS = ("fre", "tre", "bre", "gre", "cre", "dre")
WHOLE_WORDS = {"free", "great", "break", "create", "tree", "green", "dream", "bread"}


def step(carry, prefix, upstream):
    word = prefix.token_strings[-1].strip().lower()
    if word.startswith("pre"):
        if len(word) <= 4:
            value = -2.6  # a short "pre..." fragment
        elif word == "present":
            value = 0.0
        else:
            value = -0.7  # a longer "pre..." word
    elif len(word) <= 4 and word.startswith(FRAGMENT_STARTS) and word not in WHOLE_WORDS:
        value = -1.4
    elif len(word) <= 3 and word.startswith("re"):
        value = -0.2
    elif len(word) >= 8 and set(word) <= RULE_CHARS:
        value = -1.3  # a separator line
    else:
        value = 0.0
    return carry, float(value)

programs.sol:
"""Respond to split abbreviations and consonant-only letter strings.

The strongest case is an uppercase initialism continuing across tokens.
Vowels (including Y) weaken that response. Lowercase consonant clusters,
plural acronym endings, and dotted initials also respond. The state holds
the last 20 letters of the unfinished Latin word, reset per document.
The numbers are fitted response sizes, not probabilities.
"""
import re

READS = ()
VOWELS = frozenset('AEIOUYaeiouy')
CONSONANTS = 'BCDFGHJKLMNPQRSTVWXZbcdfghjklmnpqrstvwxz'
DOTTED_ABBREVIATIONS = {'e.g', 'i.e', 'a.m', 'p.m'}


def run(text):
    return len(text) - len(text.lstrip(CONSONANTS))


def score(piece, word, first):
    latin = piece.isascii() and piece.isalpha()
    vowels = sum(c in VOWELS for c in piece)
    old_vowels = sum(c in VOWELS for c in word)
    match = re.search(r'[A-Z]+$', word)
    caps = match.group() if match else ''
    if piece == 's' and word.isupper():
        return 0.72 if old_vowels == 0 else 0.20
    if latin and piece.endswith('s') and piece[:-1].isupper():
        return 1.39 if caps else 0.008
    if latin and piece.isupper():
        # An uppercase tail can form an initialism inside a camelCase name.
        if caps and caps != word:
            return 0.75 * score(piece, caps, first)
        if first:
            return 0.45 if vowels == 0 else 0.05
        if word.isupper():
            if vowels == old_vowels == 0:
                if len(word) == 1:
                    return 0.93 if len(piece) == 1 else 1.44
                return 1.66 if len(piece) == 1 else 1.34
            if vowels:
                if len(word) >= 3:
                    return 0.40 if len(piece) == 1 else 0.03
                if piece[-1] in VOWELS and vowels == 1:
                    return 0.88 if old_vowels == 0 else 0.42
                return 0.24 if len(piece) <= 2 else 0.07
            if len(word) >= 4:
                return 0.02
            trailing = run(word[::-1])
            if trailing >= 2:
                return 0.56
            if word[0] in VOWELS:
                return 0.72 if trailing else 0.28
            return 0.18
        return 0.10 if not word and run(piece) >= 2 else 0.001
    if len(piece) == 2 and piece[0] == '.' and piece[1].isascii():
        if (word + piece).lower() in DOTTED_ABBREVIATIONS:
            return 0.90 if piece[1] != 'm' else 0.74
        if piece[1].isupper():
            return 0.80 if word.isupper() else 0.20
    if len(piece) == 2 and piece[0] == '&' and caps:
        return 1.10
    # Short vowel-free fragments also cover lowercase abbreviations.
    if latin and piece.islower() and vowels == 0 and word:
        if caps and not any(c in VOWELS for c in caps):
            return 0.40 if len(piece) == len(caps) == 1 else 0.60
        if old_vowels == 0 and len(word) <= 4:
            return 0.42 if len(piece) == len(word) == 1 else 0.72
        if len(piece) <= 2 and run(word[::-1]) >= 3:
            return 0.40
    return 0.001


def step(carry, prefix, upstream):
    document = prefix.document_ids[-1]
    first = carry is None or carry[0] != document
    word = '' if first else carry[1]
    piece = prefix.token_strings[-1]
    value = score(piece, word, first)
    suffix = re.search(r'[A-Za-z]+$', piece)
    ending = suffix.group() if suffix else ''
    word = ((word if piece == ending else '') + ending)[-20:]
    return (document, word), float(value)

"""Approximate two negative lexical responses: 'each', and antiquity.

The 'each' response does not extend to 'all' or 'every'. The second family
includes civilizations, human populations and their languages,
and prehistoric life. Plural collective nouns are stronger cues than
modifiers. Token fragments count too. Unrecognized tokens predict zero.
"""
READS = ()

COLLECTIVES = {'cultures', 'societies', 'peoples'}
ANTIQUITY = {
    'homo', 'sapi', 'sapiens', 'neanderthal', 'olithic', 'neolithic',
    'paleolithic', 'palaeolithic', 'jurassic', 'dinosaur', 'dinosaurs',
    'inosaur', 'ossil', 'archae', 'archaeological',
    'archaeology', 'archeology', 'ancestor', 'ancestors', 'pottery',
    'ocene', 'chimpan', '古代', '祖先',
}
HUMAN_ORIGINS = {
    'culture', 'ulture', 'humans', 'humanity', 'mankind', 'evolution',
    'origins', 'inhabitants', 'hunter', 'settlers', 'ancient',
    'indigenous', 'aboriginal', 'empire', 'anthrop',
    'anthropology', 'excav', 'excavation', 'fossil', 'fossils',
}
LANGUAGES = {
    'languages', 'spoken', 'speakers', 'linguistic', '-speaking', 'anguage',
    '文字', '漢',
}
EUROPE = {'europe', 'europ', 'european', 'europeans', 'celtic', 'troy', '欧洲'}


def step(carry, prefix, upstream):
    token = prefix.token_strings[-1]
    word = token.strip().lower()
    doc = prefix.document_ids[-1]
    previous = carry[1] if carry and carry[0] == doc else ''
    value = 0.0
    if word == 'each':
        value = -0.795 if token[:1].isspace() else -0.65
        if token.strip() != 'each':
            value = -0.695
    elif word in {'.each', '_each'}:
        value = -0.71
    elif word in {'foreach', '.foreach', '.foreach('}:
        value = -0.35
    elif word in {'cada', 'chaque', '各', '每个', '每一', 'каждого', 'каждой'}:
        value = -0.39
    elif word.startswith(('civilization', 'civilisation')) or word == '文明':
        value = -1.2
    elif word in COLLECTIVES:
        value = -0.73
    elif word in ANTIQUITY:
        value = -0.65
    elif word in {'文化', '人类', '原始', '文字'}:
        value = -0.50
    elif word in HUMAN_ORIGINS or word in LANGUAGES or word in EUROPE:
        value = -0.35
    elif word in {'egypt', 'egyptian', 'egyptians'}:
        value = -0.45
    elif word == 'chinese':
        value = -0.30
    elif word in {'human', 'society', 'origin', 'early', 'primitive', 'period'}:
        value = -0.21
    elif word in {'ian', 'ians', 'rians', 'ensis'}:
        value = -0.20
    elif word == 'earliest':
        value = -0.56
    elif word == 'age' and previous in {'stone', 'bronze', 'iron', 'ice'}:
        value = -1.0
    return (doc, word), value

programs.haiku:
"""Predicts layers.0.mlp.down_proj:3857 as a "citizenship" detector.

The component fires almost only on the word "citizenship" (as in knowledge-graph
triples such as "X | country of citizenship | Y"). On that token it writes a strong,
nearly constant value; on the related word "citizen"/"citizens" it writes a weak one;
everywhere else it is near zero (its typical size is about 0.02-0.04, with no clear
concept behind it).

Stateless: each position is judged from its own token alone.
"""

READS: tuple[str, ...] = ()

CITIZENSHIP_VALUE = 0.8  # typical activation on " citizenship" (harvest and training: 0.65-0.9)
CITIZEN_VALUE = 0.2       # " citizen", " citizens": about a quarter of the strength


def step(carry, prefix, upstream):
    word = prefix.token_strings[-1].strip().lower()
    if word == "citizenship":
        value = CITIZENSHIP_VALUE
    elif word.startswith("citizen"):
        value = CITIZEN_VALUE
    else:
        value = 0.0
    return carry, float(value)

programs.sol:
"""Interior horizontal gaps are positive; step/procedure words are negative.

Space runs and tabs respond strongly inside a line, but ordinary indentation
is mostly suppressed. Very wide gaps and nonbreaking spaces use weaker
responses. Literal backslash-n and comment markers also weaken space gaps.
The opposite-sign word signal is strongest in 'step-by-step' and in phrases
like 'the steps'. Constants approximate training averages for these classes.
"""
READS = ()
PROCEDURES = {
    'procedure', 'procedures', 'instruction', 'instructions', 'workflow',
}
COMMENT_OR_DIFF_MARKERS = {'//', '#', '/*', '*', '+', '-'}


def gap(s, content, previous, tail):
    n, spaces, tabs = len(s), s.count(' '), s.count('\t')
    if '\xa0' in s:
        if spaces:
            return -0.12
        value = (0.80 if n >= 5 else 0.55 if n >= 3
                 else 0.20 if n == 2 else -0.03)
        return value - (0.50 if n >= 2 and previous.isspace() else 0.0)
    if not previous:  # Beginning of a row or document.
        if tabs and spaces:
            return 0.60 * (1.45 if spaces >= 5 else 1.10)
        return 0.50 if n >= 2 and not tabs else 0.02
    if not content:
        if tabs and spaces:
            return 0.25 if spaces <= 4 else 0.45
        if tabs:
            return -0.03 * min(tabs, 5)
        return 0.25 if n >= 32 else -0.02
    if previous.isspace():
        return 0.70 if n >= 28 and not tabs else 0.0
    if tabs:
        if spaces:
            return 1.45 if spaces >= 5 else 1.12 if spaces >= 2 else 1.03
        if tabs >= 2:
            return 0.90
        return 0.82 if previous[-1:].isdigit() else 0.98
    if n < 2:
        return 0.0
