    value -= min(0.8, max(0, n - 28) * 0.012)
    if tail == '\\n':
        value -= 0.46 if n <= 4 else 0.58
    elif previous.strip() in COMMENT_OR_DIFF_MARKERS:
        value -= 0.47
    elif previous[-1:].isdigit():
