import unicodedata

READS = ()

LETTER_EQUIVALENTS = str.maketrans({
    'б': 'b', 'п': 'p', 'в': 'v', 'ф': 'f', 'г': 'g',
    'а': 'a', 'о': 'o', 'у': 'u', 'е': 'e', 'и': 'i', 'і': 'i',
    'р': 'r', 'ы': 'y', 'я': 'y', 'л': 'l', 'н': 'n',
    'м': 'm', 'с': 's', 'т': 't', 'д': 'd', 'к': 'k',
    'β': 'b', 'π': 'p', 'φ': 'f', 'α': 'a',
    'ب': 'b', 'پ': 'p', 'ف': 'f', 'ا': 'a', 'բ': 'b', 'ա': 'a',
})
STRENGTH = {'b': 1.25, 'p': 0.95, 'v': 0.65,
            'f': 0.48, 'g': 0.30, 'w': 0.29}


def letter(c):
    return unicodedata.normalize('NFD', c.lower())[0].translate(LETTER_EQUIVALENTS)


