            factor = 1.28
            factor -= 0.20 * min(max(len(text) - 2, 0), 5)
            factor -= 0.15 * min(max(len(previous.strip()) - 2, 0), 5)
            if second in ('r', 'l', 'n', 's', 't'):
                factor += 0.20
            elif second in ('b', 'm', 'p', 'v', 'f'):
                factor -= 0.19
            if previous[-1].lower() in 'бпвфг':
                factor += 0.08
            value += strength * max(0.0, factor)
        elif end in 'bpv':
            if start in 'ou':
                value += strength * 0.25
            elif start == 'e':
                value -= strength * (0.42 if second == 'r' else 0.07)
            elif start == 'i':
                value += strength * (0.18 if second == 'n' else -0.15)
            elif start in 'ry':
                value -= strength * 0.20
    return (doc, text), float(value)

