"""Mostly a token-local detector of 'ro' syllables and spelling fragments.

Selected isolated ro/lo syllable spellings have the largest response. Extra
letters usually weaken it; pro is weak, and common grammatical words are
excluded. No/yes have secondary responses. This ignores contextual modulation
and the component's diffuse small responses on unrelated tokens. The rules
use literal spellings, not a pronunciation model; coefficients are fitted
approximations to training activations.
"""
READS = ()
RO_SYLLABLES = {'로', 'ロ', 'ろ', '罗', '羅', 'رو', 'โร'}
FUNCTION_WORDS = {
    'from', 'through', 'around', 'across',
    'pero', 'loro', 'nostro', 'altro', 'dentro', 'contro',
}
COMBINING_FORMS = {
    'hydro': 1.85, 'neuro': 1.75, 'electro': 1.7,
    'micro': 1.15, 'macro': 0.9, 'spectro': 0.95,
}
VOWEL_WEIGHTS = {'i': 1.0, 'e': 0.65, 'u': 0.65, 'a': 0.55, 'o': 0.3}


def spelling_response(token):
    w = token.strip().strip('_./(-:').lower()
    boundary = bool(token and token[0].isspace())
    if w == 'no':
        return 0.8 if token == 'no' else 1.05
    if w == 'yes':
        return 0.6
    if w == 'lo':
        return 0.6 if token.strip().isupper() else 0.3
    if w in RO_SYLLABLES:
        return 3.5
    if w == 'ро':
        return 2.5
    if 'ро' in w:
        return 1.0 if len(w) <= 4 else 0.35
    if w.endswith(('ロ', 'ろ')) and len(w) == 2:
        return 1.8
    if w == '으로':
        return 1.6
    if w in COMBINING_FORMS:
        return COMBINING_FORMS[w]
    if w in FUNCTION_WORDS or 'ro' not in w:
        return 0.0
    if w in ('zero', 'zeros'):
        return 0.35

    before, after = w.rsplit('ro', 1)
    if not before:
        leading = 1.0
    elif len(before) == 1:
        leading = VOWEL_WEIGHTS.get(before, 0.12)
        if before in 'bcdfgtk':
            leading = 0.75 if before in 'gk' else 0.96
    else:
        leading = 0.55 / (1 + 0.12 * (len(before) - 2))
        if boundary or before[-1] in 'aeiou':
            leading *= 0.4
    if not after:
        if w == 'ro':
            if token.strip() == 'Ro':
                return 2.6
            return 3.4 if boundary else 3.8
        if before == 'p':
            return 0.4
        return 3.6 * leading
    if before == 'p':
        return 1.0 if after in ('f', 's') else 0.0

    if after.startswith('ph'):
        tail = 2.45 / (1 + 0.13 * (len(after) - 2))
    elif after in ('sis', 'ster'):
        tail = 2.6
    elif after.startswith('s') and not after.startswith('ss'):
        tail = 2.55 / (1 + 0.55 * (len(after) - 1))
    elif after[0] in 'tbgxvy':
        tail = 2.1 / len(after) ** 0.5
        if boundary:
            tail *= 0.65
    elif after.startswith('o'):
        tail = 0.7 if after in ('ot', 'ots', 'of') else 0.05
        if before == 'b':
            tail = 2.0 / (1 + 0.12 * (len(after) - 2))
    else:
        tail = 0.85 / len(after) ** 1.2
    if len(before) >= 2:
        leading *= 0.45
    return leading * tail


def step(carry, prefix, upstream):
    return None, float(spelling_response(prefix.token_strings[-1]))

