"""Recognize colon separators by their attached punctuation.

A closing parenthesis, bracket, or quote followed by a colon gives a strong
positive response. A colon followed by a line break also responds strongly,
more so near the document's beginning. Bare colons are weaker; URL, scope,
and colon-plus-value tokens are not treated as content-introducing colons.
Capitalized preceding words slightly strengthen the separator response.
The newline after a user token gets a smaller positive response. Chat-control
markers get small negative responses. Other tokens are predicted as zero,
leaving the component's weaker lexical variation unexplained.
"""

READS = ()


def early(position, scale):
    return 1.0 / (1.0 + position / scale)


def separator(token, position):
    before, _, after = token.replace('：', ':').partition(':')
    if ':' in after:
        return -0.04  # Repeated colons, e.g. C++ scope separators.
    if after.strip(' \t\r\n') not in ('', '\\'):
        return -0.10  # A colon joined to its value or URL punctuation.
    lines = after.count('\n')
    if before.endswith(')'):
        if lines:
            value = 1.11 + 0.95 * early(position, 30)
            if lines > 1:
                value += 0.14
        elif after == '\\':
            value = 1.07 + 0.73 * early(position, 5)
        else:
            value = 1.42 + 0.92 * early(position, 20)
        # Additional closing parentheses strengthen the response.
        extra_closes = len(before) - len(before.rstrip(')')) - 1
        value += 0.35 * max(0, extra_closes)
        if before[:1].isspace():
            value += 0.25
        return value
    if before.endswith(']'):
        return 1.18 + 0.40 * early(position, 30)
    if before.endswith('}'):
        return 0.65 + 0.35 * early(position, 50)
    if before.endswith(('"', "'")):
        if lines:
            return 0.90 + 2.20 * early(position, 5)
        return 0.50 if '\\' in before else 0.73
    if before.endswith('`'):
        return 0.78 + 0.52 * early(position, 50)
    if before.endswith('?'):
        return 0.84
    if before.endswith('*'):
        return 0.28 + 0.30 * early(position, 10)
    if lines:
        if position == 0:
            return 2.28 if lines == 1 else 2.20
        if lines == 1:
            value = 0.56 + 0.95 * early(position, 10)
            return value - (0.20 if '：' in token else 0.0)
        if lines == 2:
            return 0.48 + 0.98 * early(position, 15)
        return 0.35 + 0.92 * early(position, 5)
    if position == 0:
        return 0.84
    if before and before.isspace():
        return 0.16 + 0.17 * early(position, 30)
    return 0.085 + 0.075 * early(position, 10)


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    if carry is None or carry[0] != doc:
        previous, position = '', 0
    else:
        _, previous, position = carry
    token = prefix.token_strings[-1]
    if ':' in token or '：' in token:
        value = separator(token, position)
        # Capitalized labels differ from ordinary lower-case prose.
        if position and token.strip(' \t\r\n') in (':', '：'):
            word = previous.strip()
            if word.isalpha():
                if word.istitle() or word.isupper():
                    value += 0.10
                elif word.islower():
                    value -= 0.04
            elif word.isdecimal() and token.endswith('\n\n'):
                value += 0.09
    elif token == '\n' and previous == 'user':
        value = 0.22 + 0.17 * early(position, 10)
    elif token == '<|im_end|>':
        value = -0.10
    elif token == '</tool_response>':
        value = -0.17
    elif token == '<think>':
        value = -0.16
    else:
        value = 0.0
    return (doc, token, position + 1), float(value)

