SURFACE_TABLE = {"surface", "surfaces", "table", "tables"}
EXPRESS = {"express", "expressed", "expresses", "expressing", "expression", "expressions"}
DISPLAY = {"statement", "statements", "manifest", "chart", "charts", "sheet", "sheets",
           "instrument", "instruments", "published"}
# Chinese words containing 表; the single character 表 is the strongest.
CHINESE = {"表": 5.0, "表面": 3.0, "外表": 3.0, "表现": 2.0, "表达": 1.6, "表示": 1.5,
           "表格": 2.0, "图表": 2.5, "列表": 2.0, "发表": 2.4}


def strength(token):
    """How strongly one token (decoded alone) triggers the component."""
    stripped = token.strip()
    if stripped in CHINESE:
        return CHINESE[stripped]
    if "表" in token:
        return 1.5
    word = re.sub(r"[^a-z]", "", token.lower())
    if word in SURFACE_TABLE:
        return 1.7
    if word in EXPRESS:
        return 1.2
    if word in DISPLAY:
        return 0.8
    if word == "list":
        return 0.3
    return 0.0


