def step(carry, prefix, upstream):
    text = prefix.token_strings[-1]
    tabs = text.count('\t')
    if not tabs:
        return None, 0.0

    same_doc = (len(prefix.document_ids) > 1 and
                prefix.document_ids[-1] == prefix.document_ids[-2])
    previous = prefix.token_strings[-2] if same_doc else ''
    if text.strip(' \t\r\n'):
        value = 0.07
    elif not text.endswith('\t'):
        value = -0.18 if tabs >= 2 else 0.0
    elif ' ' in text:
        value = -0.56
    elif tabs >= 2:
        value = -0.77
    elif not same_doc:
        value = -0.015
    elif '\t' in previous and '\n' not in previous:
        value = -0.09 if previous.count('\t') == 1 else -0.02
    elif previous.endswith('\n'):
        value = -0.63
    elif previous.isspace() or previous.strip().isdigit():
        value = -0.39
    else:
        value = -0.48
    return None, value

