"""Indentation-tab detector (layers.0.mlp.down_proj:3868).

This component writes a strong negative signal on the tab characters that indent
source code and other tab-indented text. It is silent on almost everything else.

Rule, per token (a token is one BPE piece, decoded alone):
  * a token of two or more tabs (optionally after spaces), i.e. a deeply indented
    line: about -0.75;
  * a single tab that starts a line (previous token ends in a newline): about -0.6;
  * a single tab after a digit (line-number gutters such as "  413<TAB>"): about -0.4;
  * a single tab elsewhere in a line: about -0.25;
  * a tab that continues an earlier run of tabs, or a token with a tab followed by
    spaces or text: 0;
  * anything without a tab: 0.

It explains about 30% of the variance; the remainder is small, token-specific noise.
"""

READS = ()


def _indent_tabs(s):
    """Number of tabs in s if s is spaces and tabs ending in a tab, else 0."""
    if s.endswith("\t") and set(s) <= {" ", "\t"}:
        return s.count("\t")
    return 0


def step(carry, prefix, upstream):
    cur = prefix.token_strings[-1]
    prev = prefix.token_strings[-2] if len(prefix) > 1 else "\n"
    n = _indent_tabs(cur)
    if n == 0:
        return carry, 0.0
    if n >= 2:
        return carry, -0.75
    if _indent_tabs(prev) or prev == "\t":
        return carry, 0.0
    if prev == "" or prev.endswith("\n"):
        return carry, -0.62
    if prev[-1:].isdigit():
        return carry, -0.4
    return carry, -0.25

