    'conf': 0.14,
    'configuration': 0.21,
    'configurations': 0.13,
    'configure': 0.11,
    'configured': 0.11,
    'configurable': 0.16,
    'configuring': 0.06,
    'settings': 0.17,
    'options': 0.08,
    'params': 0.23,
    'metadata': 0.17,
    'debug': 0.18,
    'admin': 0.29,
    'editor': 0.19,
}


