        if age == 0:
            return -6.7
        if s.startswith(' '):
            value = -5.4
            if previous[-1:].isspace():
                value -= 0.35
        elif previous.endswith(('\n', '\\n')):
            value = -5.2 if previous.endswith('\n\n') else -5.7
        elif previous.endswith('['):
            value = -5.9
        elif previous.endswith('/'):
            value = -6.4
        else:
            value = -3.6
