        return {2: -0.77, 3: -0.86, 4: -1.2, 5: -0.58}.get(len(text), -1.1)
    if text and len(text) >= 8 and len(set(text)) == 1 and text[0] in '=-':
        return -0.9
    if s == '</think>':
        return -1.2
    if s == '<think>':
        return -0.34
    if s == '【':
        return -0.7
    if s == 'bf':
        if previous.endswith('math'):
            return -3.0
        if previous.endswith('text'):
            return -2.5
        return -1.8 if previous.endswith('\\') else -1.0
    if s in ('bb', 'cal') and previous.endswith('math'):
        return -1.0 if s == 'bb' else -0.7
    if s == 'boxed' and previous.endswith('\\'):
        return -0.74
    if text.lower() == 'bold':
        return -1.5
    if text in ('strong', 'strongly'):
        return -1.3 if text == 'strong' and previous.endswith(('<', '</')) else -0.45
