BOLD = {"**"}
BOLD_ENDINGS = {")**", "**,", "**\n"}
MARKERS = {"__", " __", "/__", ".__", "##", " ##", "###", "####", "/**", " /**", "/**\n", " /**\n"}
WORDS = {"bf", "bb", "bold", "strong", "</think>"}
SEPARATOR = re.compile(r"\s?([=\-/#_*~])\1{7,}\n?")


def step(carry, prefix, upstream):
    tok = prefix.token_strings[-1]
    if tok in BOLD_AFTER_SPACE:
        value = -5.9
    elif tok in BOLD:
        value = -4.1
    elif tok in BOLD_ENDINGS:
        value = -2.5
    elif "**" in tok:
        value = -1.0
    elif tok in MARKERS or tok in WORDS:
        value = -1.1
    elif SEPARATOR.fullmatch(tok):
        value = -0.9
    else:
        value = 0.0
    return carry, value

