                value = (-0.75, -2.40, -1.65)[kind] + (0.25 if newline else 0.0)
            elif tail.startswith((first, '/', '\\', '<', '[', '{')):
                value = -0.30
            elif tail.startswith(('./', '../', '--', '..')):
                value = -0.25
            elif tail[:1] in ('.', '+', '-', ':', '=', '\n', '\r'):
                value = -0.80
    elif token == ']':
        value = -0.10
    return (doc, (before + token)[-2:]), float(value)

programs.luna:
"""Approximate a small nominal-phrase feature.

The harvested strong responses often land on a content word within a few words of a
possessor ("my case", "their plans", or "her replacement"). Predict a modest
positive activation for that familiar construction; otherwise predict zero.
"""

READS = ()

_POSSESSORS = {
    "my", "your", "his", "her", "its", "our", "their",
}
_NONWORDS = {
    "a", "an", "the", "and", "or", "but", "if", "as", "at", "by",
    "for", "from", "in", "into", "of", "on", "to", "with", "without",
    "about", "after", "before", "between", "through", "under", "over",
    "who", "what", "when", "where", "which", "that", "this", "these",
    "those", "i", "you", "he", "she", "it", "we", "they", "me", "him",
    "them", "us", "am", "is", "are", "was", "were", "be", "been", "being",
    "do", "does", "did", "have", "has", "had", "can", "could", "will",
    "would", "shall", "should", "may", "might", "must", "not", "no",
}


def _plain_word(token):
    return token.strip().strip("\"'’.,:;!?()[]{}")


def _is_possessor(token):
    raw = token.strip()
    if raw in {"'s", "’s"}:
        return True
    word = _plain_word(token).lower()
    if word in _POSSESSORS:
        return True
    if word in {"it's", "that's", "there's", "here's", "what's", "who's"}:
        return False
    return word.endswith(("'s", "’s"))


def step(carry, prefix, upstream):
    t = prefix.position
    current = prefix.token_strings[t]
    word = _plain_word(current)

    # Require a whole, space-starting word rather than a continuation piece.
    if not word.isalpha() or len(word) < 2 or not current[:1].isspace():
        return None, 0.0
    if word.lower() in _NONWORDS:
        return None, 0.0

    # Look back only within this document for a recent possessive cue. This
    # allows a short modifier such as "diffusion" between determiner and noun.
    doc = prefix.document_ids[t]
    start = max(0, t - 3)
    for i in range(t - 1, start - 1, -1):
        if prefix.document_ids[i] != doc:
            break
        if _is_possessor(prefix.token_strings[i]):
            return None, 0.45
    return None, 0.0

