    'this': 1.08, 'those': 0.83, 'what': 1.10, 'which': 0.75,
    'whether': 0.98, 'where': 0.06, 'how': 0.06, 'who': 0.23,
}
PREPOSITIONS = set("""
    of in for to at with on from into by about under over through without
    within between against upon beyond around before after during
""".split())
# Verbs introducing a reported proposition; ordinary inflections below.
REPORTING = set("""
    note realize show know say state suggest indicate reveal conclude observe
    see imply notice understand explain mention discover find recognize prove
    acknowledge argue learn tell seem appear follow demonstrate
""".split())
THINKING = set("""
    believe ensure consider remember assume suppose think verify mean expect
    require intend claim report determine insist confirm recall
""".split())
IRREGULAR = {
    'said': 'say', 'known': 'know', 'knew': 'know', 'found': 'find',
    'seen': 'see', 'saw': 'see', 'shown': 'show', 'told': 'tell',
    'thought': 'think', 'understood': 'understand',
}


def verb_response(word):
    base = IRREGULAR.get(word, word)
    forms = {base}
    if base.endswith('ies'):
        forms.add(base[:-3] + 'y')
    for ending in ('s', 'es', 'ed', 'ing'):
        if base.endswith(ending):
            stem = base[:-len(ending)]
            forms.update((stem, stem + 'e'))
