        return 1.50
    if forms & THINKING:
        return 1.95
    return 2.65


def that_response(previous):
    word = previous.strip().lower()
    if word == 'such':
        return 0.72
    if word == 'fact':
        return 1.28
    if word in ('way', 'ways', 'manner', 'given', 'aware', 'evident'):
        return 1.55
    # Personal objects and generic antecedents.
    if word in ('me', 'us', 'him', 'her', 'them', 'you', 'it', 'one',
                'ones', 'things', 'those', 'something'):
        return 2.00
    if word in ('clear', 'true'):
        return 2.00
    if word == 'so':
        return 1.97
    if word in ('and', 'or'):
        return 4.40
    if word in ('but', 'than', 'as', 'except', 'if'):
        return 3.50
    if any(c in word for c in ',;:—–'):
        return 3.80
    if not word or not any(c.isalnum() for c in word):
        return 3.15
    if word in ('is', 'was', 'be', 'been', 'being'):
        return 2.30
    if word in PREPOSITIONS:
        return 2.75 if word in ('in', 'with') else 3.00
