def step(carry, prefix, upstream):
    token = prefix.token_strings[-1]
    word = token.strip().lstrip("._-$([{<>'\"“‘—–,/")
    lower = word.lower()
    same_doc = (len(prefix.token_ids) > 1 and
                prefix.document_ids[-2] == prefix.document_ids[-1])
    previous = prefix.token_strings[-2] if same_doc else ''
    prev = previous.strip().lower()
    attached = token.strip() != word
    capital = bool(word and word[0].isupper())
    if lower == 'that':
        if capital:
            value = 4.10 if word == 'THAT' else 4.86
        elif attached:
            value = 4.25
        elif not token.startswith(' '):
            value = 3.48
        elif not same_doc:
            value = 3.42
        else:
            value = that_response(previous)
            if previous.strip()[:1].isupper():
                value += 0.30
    else:
        value = WORDS.get(lower, 0.0)
        if capital:
            value = CAPITALIZED.get(lower, value)
        elif lower in ('che', 'que', 'dat') and not token.startswith(' '):
            value = {'che': 0.13, 'que': 0.20, 'dat': 0.95}[lower]
        elif lower == 'which' and token.startswith(' '):
            if ',' in previous or prev in PREPOSITIONS:
                value = 0.30 if prev == 'in' else 0.53
            else:
                value = 0.0
        if lower == 'this':
            if attached or token.startswith('\t'):
                value = 1.30
            elif not capital and (',' in previous or prev in ('and', 'or')):
                value = 1.23
            elif not capital and prev in ('do', 'does', 'doing', 'like', 'is'):
                value = 0.80
    return None, float(value)

