programs.sol:
"""Detect formatting tokens: padding spaces, tabs and escaped backslashes.

The largest responses are space-only tokens of widths 2--4. Line-start
padding usually responds more strongly than padding within a line. Longer
runs depend on their width modulo four: whole indentation units are positive,
while the common 4k-1-space pieces are weak or negative. Ordinary text is zero.
Short nonbreaking padding and doubled backslashes also respond positively.
This ignores small word-specific responses and finer context.
"""
import re

READS = ()
# Width: (inside a line, immediately after a newline).
SHORT_SPACES = {
    2: (1.55, 1.95),
    3: (1.00, 1.02),
    4: (1.43, 1.68),
    5: (.46, .52),
    6: (.54, .78),
}
TAB_SPACES = {1: .56, 2: .81, 3: .47, 4: .88, 5: .23}


def spaces(n, line_start):
    if n == 1:
        return .44 if line_start else 0.0
    if n in SHORT_SPACES:
        return SHORT_SPACES[n][int(line_start)]
    if n >= 64:
        return .30 if n == 64 else 0.0
    if n % 4 == 3:
        return (-.02 if line_start else -.07) if n == 7 else -.13
    if n % 4 == 0:
        return .84 if line_start else .64
    if n % 4 == 2:
        return .60 if line_start else .44
    return .13 if line_start else .07


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    s = prefix.token_strings[-1]
    first = carry is None or carry[0] != doc
    line_start = not first and carry[1].endswith('\n')
    value = 0.0
    if s and s == ' ' * len(s):
        value = spaces(len(s), line_start)
        if first and len(s) in (1, 2, 3, 4, 5, 6):
            value = (-.07, 2.06, 1.07, 2.36, .72, 1.04)[len(s)-1]
    elif s.isspace():
        if '\n' in s:
            padding = s.rstrip('\r\n')
            if padding in ('   ', '    ', '     '):
                value = .35
            elif '\t' in s:
                value = -.08 * min(s.count('\t'), 4)
            elif len(padding) >= 7:
                value = -.12
        elif '\xa0' in s and 1 < len(s) <= 4:
            value = .82
        elif '\t' in s:
            n = len(s) - len(s.rstrip(' '))
            if n:
                value = TAB_SPACES.get(n, .53 if n % 4 == 0 else -.02)
            elif s.startswith(' '):
                value = .65
            elif s.count('\t') <= 2:
                value = .05 if line_start else -.09
            else:
                value = -.09
    else:
        runs = re.findall(r'\\{2,}', s)
        if runs:
            n = max(map(len, runs))
            value = .54 if n == 3 else (1.3 if n >= 4 else 1.1)
    return (doc, s), float(value)

"""A local alternatives-and-separators detector.

Predict a response after 'or', strongest for quantities and negation. Vertical
bars respond themselves and prime the next field or pipeline command. Bars at
document starts, bars following bar-ending tokens, and some immediate closing
bars get negative predictions. Spacing, case, numbers, and named word classes
modulate these responses. Away from these cues, predict zero. State resets at
each document boundary.
"""
import math

READS = ()
NUMBER_WORDS = set('one two three four five six seven eight nine ten'.split())
TABLE_RELATIONS = {'member', 'located', 'position', 'sport', 'community'}
TABLE_CLASSES = {'instance', 'country', 'occupation', 'given', 'part'}


def after_or(word):
    if word in {'more', 'so'}:
        return 3.45
    if word == 'less':
        return 2.8
    if word in {'not', 'all'}:
        return 2.65
    if word in {'no', 'none', 'nothing', 'some', 'both'}:
        return 2.0
    if word in NUMBER_WORDS:
        return 0.6 if word == 'one' else 1.9 if word == 'two' else 1.5
    if word in {'equal', 'better', 'fewer'}:
        return 1.8
    if word in {'maybe', 'perhaps', 'if', 'even', 'of', 'with'}:
        return -0.4
    if word in {'another', 'something', 'just'}:
        return 1.3
    if word in {'her', 'his', 'its', 'any', 'otherwise'}:
        return 0.9
    if word in {'in', 'on', 'after', 'without', 'other', 'similar'}:
        return 0.7
    return 0.8 if word.isdigit() or not word else 0.3


def after_bar(token, previous):
    word = token.strip().lower()
    spaced = previous.startswith(' ') and not previous.strip().endswith('||')
    value = 1.5 if spaced else 1.1
    if token.strip()[:1].isupper():
        value = 1.2 if spaced else 0.9
    if word.isdigit():
        value = 3.0 if spaced else 2.2
    elif len(word) == 1 and word.isalpha() and not token[:1].isspace():
        value = 2.7 if spaced else 1.4
    if '\n' in previous or '\n' in token:
        return 0.5
    if token.isspace():
        offset = 0.0 if spaced else 0.8 if previous.strip() == '|' else 1.2
        return 3.4 - 0.7 * math.log(len(token)) - offset
    if spaced:
        if word == 'grep':
            return 5.0
        if word in {'head', 'tail', 'cut', 'wc'}:
            return 3.2
        if word in {'awk', 'sort'}:
            return 4.2
        if word == 'sed':
            return 2.8
        if word in {'null', 'none', 'undefined', 'nil'}:
            return 6.7 if word == 'null' else 5.7 if word == 'none' else 5.0
        if word in {'place', 'parent', 'the', 'a', 'an'}:
            return 2.7
        if word in TABLE_RELATIONS:
            return 2.35
        if word in TABLE_CLASSES:
            return 1.7
    return value


def step(carry, prefix, upstream):
    doc, token = prefix.document_ids[-1], prefix.token_strings[-1]
    fresh = carry is None or carry[0] != doc
    previous, was_or, followed_bar = ('', False, False) if fresh else carry[1:]
    word = token.strip().lower()
    bar_before = previous.rstrip().endswith('|') and '<|' not in previous
    value = 0.0
    if was_or and (token[:1].isspace() or word.isdigit()):
        value = after_or(word)
        if token.strip()[:1].isupper():
            value *= 0.4
        if '\n' in token:
            value = 0.2
    if word.startswith('|'):
        doubled = word.startswith('||')
        value = 0.0 if doubled else 1.3
        if fresh:
            value = (-2.2 if doubled else -3.6) if token.startswith(' ') else (
                -3.5 if doubled else -4.8
            )
        elif bar_before:
            value = -2.5 if '\n' in token else -4.0
        elif '\n' in token:
            value = 0.1
        elif word not in {'|', '||'} and not word[1:2].isalpha():
            value = 1.3 if word[1:2] == '\\' else -0.3
        elif previous == ' ':
            value = -1.1 if doubled else -0.4
        elif previous.isspace() and '\n' not in previous:
            value = 0.8
        elif word == '|' and followed_bar and not previous[:1].isspace():
            value = -0.8
        elif previous[-1:].isdigit():
            value = -0.1 if doubled else 1.15
        elif not previous[-1:].isalpha() and word == '|':
            value = 1.65
    elif bar_before:
        value = after_bar(token, previous)
    # A suffix in a word like 'color' is not the conjunction 'or'.
    is_or = word == 'or' and (
        token[:1].isspace() or fresh or not previous[-1:].isalpha()
    )
    return (doc, token, is_or, bar_before), float(value)

programs.haiku:
"""Layer-0 MLP down_proj component 3879.

Plain-terms summary: this component reads vertical bars "|" used as separators, and the
first token after one. It is strongest on the token right after a bar, most of all when that
token is a shell command after a pipe ("cmd 2>&1 | head", "| grep", "| tail") or a run of
spaces (table padding), and moderately strong on a bar that follows a word, a number or a
closing bracket ("| country |"). It is strongly negative on a bar that follows a line-ending
bar ("|\\n|", the spam link lists), and mildly negative on the first word of such a line.
It is also mildly positive on the word after "or" in quantity phrases ("one or more",
"two or less", "or so", "or not"). Everywhere else it is near zero.

Values are rough averages of the activation in each case. The program has no state, so it
reads only the newest token and the one before it.
"""

READS = ()

MID_BARS = {"|", " |"}
LINE_END_BARS = {"|\n", " |\n"}
ALL_BARS = MID_BARS | LINE_END_BARS
SHELL_AFTER_PIPE = {" head", " tail", " grep", " sort", " wc", " less", " more", " awk",
                    " sed", " xargs", " tee", " cat", " uniq", " tr", " cut"}
OR_WORDS = {" or", " Or"}
AFTER_OR = {" more", " less", " fewer", " so", " not", " equal", " than", " other",
            " two", " three", " several", " any", " a"}

BAR = 1.2              # a bar after a word
BAR_AFTER_DIGIT = 1.0  # a bar after a number
BAR_AFTER_CLOSE = 1.8  # a bar after ")", "]" or a quote
BAR_AFTER_LINE_BAR = -3.8  # a bar right after a line-ending bar
AFTER_BAR_WORD = 1.5   # a word right after a bar
AFTER_BAR_SPACES = 2.6  # a run of spaces right after a bar
AFTER_BAR_SHELL = 3.5  # a shell command right after a bar
AFTER_LINE_BAR = -1.0  # the first word after a line-ending bar
AFTER_OR_QUANT = 1.9   # the word after "or" in a quantity phrase
AFTER_OR_OTHER = 0.3   # any other word after "or"


def step(carry, prefix, upstream):
    cur = prefix.token_strings[-1]
    same_doc = len(prefix) > 1 and prefix.document_ids[-2] == prefix.document_ids[-1]
    prev = prefix.token_strings[-2] if same_doc else ""
    if cur in ALL_BARS:
        if prev in LINE_END_BARS:
            value = BAR_AFTER_LINE_BAR
        elif prev[-1:].isdigit():
            value = BAR_AFTER_DIGIT
        elif prev[-1:] in (")", "]", '"', "'"):
            value = BAR_AFTER_CLOSE
        else:
            value = BAR
    elif prev in LINE_END_BARS:
        value = AFTER_LINE_BAR
    elif prev in MID_BARS:
        if cur in SHELL_AFTER_PIPE:
            value = AFTER_BAR_SHELL
        elif cur.strip() == "":
            value = AFTER_BAR_SPACES
        else:
            value = AFTER_BAR_WORD
    elif prev in OR_WORDS:
        value = AFTER_OR_QUANT if cur in AFTER_OR else AFTER_OR_OTHER
    else:
        value = 0.0
    return carry, float(value)

