"""Layer-0 MLP output, component 3880: a "graph / probability / variable word" detector.

What it does: the component is mostly silent. Its activation is clearly positive on a
small set of technical nouns, the words for graph elements (node, edge, vertex),
probability, variables, and the players of game-theory examples (Alice, Bob, player,
voter), plus the index "_i", and "each"/"none"/"random" to a lesser degree. Everywhere
else it sits near zero. The program predicts a fixed value per such word (the mean
activation measured on training text) and 0 for every other token.

It is a word-level program: it looks only at the current token and never at context.
"""

READS = ()

# Words are compared lowercased with surrounding spaces removed, so " Node", "node"
# and "\tnode" all count.
GRAPH_WORDS = {"node", "nodes", "edge", "edges", "vertex", "vertices", "nodetype"}
PROBABILITY_WORDS = {"probability", "probabilities", "prob", "probabil"}
VARIABLE_WORDS = {"variable", "variables"}
PLAYER_WORDS = {"alice", "bob", "player", "players", "voters"}
OTHER_WORDS = {
    "_i": 0.40,
    "each": 0.15,
    "none": 0.13,
    "random": 0.17,
    "vectors": 0.17,
    "pairs": 0.15,
    "independent": 0.12,
}


def weight(word):
    """Predicted activation for a token, from its text alone."""
    w = word.strip().lower()
    if w in GRAPH_WORDS:
        return 0.37
    if w in PROBABILITY_WORDS:
        return 0.46
    if w in VARIABLE_WORDS:
        return 0.31
    if w in PLAYER_WORDS:
        return 0.30
    return OTHER_WORDS.get(w, 0.0)


def step(carry, prefix, upstream):
    # Each position depends only on the token it is about; no state is carried.
    return None, float(weight(prefix.token_strings[-1]))

programs.sol:
"""Respond to phrase-ending punctuation clusters, not ordinary commas.

A comma sharing a token with a quote, parenthesis, or other punctuation gets a
large positive response. Semicolons and quoted sentence endings get smaller
responses. Recent code/math syntax lowers several responses; trailing line
breaks or escape characters suppress them. This captures the strong feature,
not the many small, word-specific fluctuations in the component. Closing
parentheses also depend on the length of their parenthetical span; their
negative response saturates for long spans.
"""
import re

READS = ()
QUOTES = frozenset('\"\'“”‘’«»')
CLOSERS = frozenset(')]}>）】》')
CODE = re.compile(
    r'[{}_=\\]|\b[a-z_]\w*\(|\b(?:SELECT|INSERT|VALUES)\b'
    r'|(?:^|\n)\s*(?:def |class |import |return |const |var |let )'
)


def response(s, recent, in_quote, span=None, spaced_opener=False):
    if any(c.isalnum() for c in s):
        return -0.001
    b = s.strip()
    code = bool(CODE.search(recent))
    if '\n' in s or '\r' in s or s.endswith('\\'):
        if ',' in b or '，' in b:
            return 0.23 if any(c in b for c in CLOSERS) else -0.03
        return -0.06 if ';' in b else -0.001
    if span is not None and b in {')', ').', '),', ');'}:
        # Short parentheticals, especially ones separate from a function name.
        length = min(20, span)
        number = recent[-1:].isdigit()
        if b == ')':
            return max(-0.20, 0.13 - 0.025 * length - 0.06 * code
                       + 0.09 * spaced_opener + 0.05 * number)
        if b == ').':
            return (0.14 - 0.007 * length - 0.08 * code
                    + 0.10 * spaced_opener + 0.07 * number)
        if b == '),':
            return (1.09 - 0.015 * length - 0.22 * code
                    + 0.25 * spaced_opener + 0.25 * (s != b))
        return 0.70 - 0.35 * code + 0.43 * spaced_opener + 0.06 * number
    if ',' in b or '，' in b:
        if b in {',', '，'}:
            return 0.65 if s != b else -0.02
        if b.startswith((',', '，')) and b[-1:] in QUOTES:
            if s != b or '“' in b:
                return 0.0
            if '”' in b or '’' in b:
                return 2.35
            if "'" in b and '"' not in b:
                return 0.15 if code else 2.0
            return (1.5 if in_quote else 0.1) if code else 2.25
        if not b.endswith((',', '，')):
            return 0.0
        if any(c in b for c in QUOTES):
            if any(c in b for c in '“”‘’«»'):
                return 1.3 if '，' in b else 1.8
            if '\\' in b:
                return 0.64
            return (0.72 if code else 1.9) if '"' in b else 0.6
        if ')' in b or '）' in b:
            if '()' in b and s == b:
                return 0.53
            value = 0.86 if '，' in b else (0.87 if code else 1.22)
            return value + (0.4 if any(c in b for c in '.?!%') else 0.0)
        return 1.2 if any(c in b for c in '%*!?-:') else 0.86
    if ';' in b:
        if b == ';':
            return 0.23 if code else 0.56
        if b == ');':
            return 0.32 if code else 1.08
        if any(c in b for c in '”’»'):
            return 1.6
        return 0.99 if b == '.;' else 0.35
    if any(c in b for c in QUOTES):
        # Quotation marks adjacent to sentence-ending punctuation.
        sentence_end = any(c in b for c in '.。?!')
        if s == b and len(b) == 2 and sentence_end and '“' not in b:
            return 0.05 if code and b[0] in QUOTES else 0.6
        if b.endswith(')'):
            return 0.05 if code else 0.4
        return 0.22 if b == '”' else 0.0
    if b == ')':
        return 0.16 if s != b else (0.0 if code else 0.07)
    if b.endswith(')') and any(c in b for c in '.%*?'):
        return 0.65 if '.' not in b else 0.43
    if b.endswith('.') and any(c in b for c in CLOSERS):
        return -0.1 if '()' in b else 0.16
    return -0.17 if s == '`' else -0.001


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    if carry is None or carry[0] != doc:
        recent, in_quote, parentheses = '', False, []
    else:
        _, recent, in_quote, parentheses = carry
    s = prefix.token_strings[-1]
    span = prefix.position - parentheses[-1][0] if parentheses else None
    spaced = parentheses[-1][1] if parentheses else False
    value = response(s, recent, in_quote, span, spaced)
    for i, c in enumerate(s):
        previous = s[i - 1] if i else recent[-1:]
        if c == '(':
            parentheses.append((prefix.position, previous.isspace()))
        elif c == ')' and parentheses:
            parentheses.pop()
        if c == '"' and previous != '\\':
            in_quote = not in_quote
    return (doc, (recent + s)[-256:], in_quote, parentheses), float(value)

