"""Punctuation is a weak cue here, strongest when a comma sits by a quote."""
import unicodedata

READS = ()
BASELINE = 0.00385
QUOTES = frozenset("\"'‘’“”«»‹›")
CLOSING_MARKS = frozenset(")]}>】」』〉》〕）］｝")


def step(carry, prefix, upstream):
    visible = [c for c in prefix.token_strings[-1] if not c.isspace()]
    if not visible or any(unicodedata.category(c)[0] not in "PS"
                          for c in visible):
        return None, BASELINE

    if any(c in QUOTES for c in visible):
        strength = 2.0 if any(c in ",，" for c in visible) else 0.7
    elif any(c in CLOSING_MARKS for c in visible):
        strength = 0.55
    elif any(c in ";；" for c in visible):
        strength = 0.5
    else:
        strength = 0.12
    return None, BASELINE + 0.2 * strength

