"""TH-spelling detector: negative on short TH fragments and word endings.

Short TH fragments are stronger than longer words. Common grammatical words
are exceptions, and ordinal suffixes use the preceding digit. PH endings are
a weaker parallel; several non-Latin dental/aspirated spellings and the
Chinese ordinal marker have explicit responses. All other tokens are near zero.
"""
import re
READS = ()

FUNCTION_WORDS = set('''the this that these those them they their there then
than thus though through with other another together either neither whether
further therefore themselves both although rather something anything
everything nothing'''.split())
COMMON_WEAK_WORDS = set('''health healthy length strength python algorithm
author authority brother think thank throw three thing things thin
mathrm github ithub'''.split())
WEAK_ENDINGS = set('''path math width growth earth worth wealth smith youth
faith month auth lith teeth tooth smooth cloth'''.split())


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    previous = carry[1] if carry is not None and carry[0] == doc else ''
    token = prefix.token_strings[-1]
    word = re.sub(r'^[^\w]+|[^\w]+$', '', token).strip('_')
    w = word.lower()
    value = -0.003
    if w.startswith('第'):
        value = -1.9 / len(w)
    elif w in {'θ', 'ϑ'}:
        value = -1.6
    elif 'ث' in w:
        value = -max(0.3, 5.0 - 0.7 * (len(w) - 1))
    elif w in {'ถ', 'ธ', 'थ'}:
        value = -2.2
    elif w in {'ท', 'ース'}:
        value = -0.85
    elif w in {'þ', 'ð', 'ذ'}:
        value = -0.65
    elif w in FUNCTION_WORDS or w in COMMON_WEAK_WORDS:
        value = 0.0
    elif w.startswith(('with', 'other', 'there', 'health', 'length')):
        value = 0.0
    elif w in {'st', 'nd', 'rd'} and previous.strip().isdigit():
        value = -0.7
    elif w == 'second':
        value = -0.55
    elif 'th' in w and w.isascii():
        before, after = w.split('th', 1)
        if w in {'th', 'ths'}:
            value = -4.7 if previous[-1:].isalpha() else -3.35
            if word == 'Th':
                value = -2.05
            elif token[:1].isspace():
                value = -3.15 if word == 'th' else -2.2
        elif len(w) == 3 and w.endswith('th'):
            value = {'a': -3.2, 'e': -6.0, 'i': -4.2,
                     'o': -5.4, 'u': -4.8}.get(before, -4.0)
        elif w in WEAK_ENDINGS:
            value = -1.15
        elif w.startswith('third'):
            value = -1.6
        elif w in {'north', 'south'}:
            value = -1.6 - 0.4 * word[:1].isupper()
        elif not after:
            value = -max(0.5, 4.4 - 0.6 * len(before))
            if w.endswith('oth'):
                value = -3.5
            if w == 'forth':
                value = -3.9
            elif w == 'death':
                value = -1.9
        elif w.startswith('eth'):
            value = -2.0
        elif before:
            value = -max(0.1, 1.2 - 0.15 * len(after))
        elif w == 'thorough':
            value = -1.7
        elif w.startswith(('thick', 'theta', 'thesis')):
            value = -0.75
        elif w.startswith('thro') and len(w) < 6:
            value = -2.0
        elif len(w) < 5:
            value = -0.8
        else:
            value = -0.2
    elif w.endswith(('ph', 'phs')):
        value = -2.1 if w == 'aph' else -0.85
    return (doc, token), float(value)

"""Estimate a local spelling-transition signal centered on the letter D.

The harvested activations are strongest after D-ending fragments. This program
predicts positive O/U continuations and often negative E/T continuations, with
larger gains for short fragments. Spelling prefixes, common suffixes, and a
few marked vowels refine the contrast. T/TH/DS endings get weaker gains.

Only the preceding token's gain is remembered. Whitespace-starting tokens and
document starts predict zero. Small, ordinary token-specific biases are omitted.
"""
import unicodedata

READS = ()
EQUIVALENTS = str.maketrans({
    'д': 'd', 'о': 'o', 'у': 'u', 'и': 'i', 'е': 'e', 'а': 'a',
    'т': 't', 'с': 's', 'н': 'n', 'г': 'g', 'ж': 'j', 'ы': 'y',
    'р': 'r', 'б': 'b', 'к': 'k', 'л': 'l', 'м': 'm', 'ф': 'f',
    'з': 'z', 'в': 'v', 'п': 'p', 'э': 'e', 'і': 'i',
    'د': 'd', 'و': 'u', 'ا': 'a', 'ی': 'y',
    'δ': 'd', 'ο': 'o', 'ω': 'o', 'υ': 'u', 'ι': 'i', 'τ': 't',
    'ı': 'i', 'ø': 'o', 'å': 'o', 'œ': 'o',
})
ONSET = {
    'o': .65, 'u': .40, 'i': .10, 'a': .05, 'e': .05,
    't': -.60, 'g': -.26, 'b': -.18, 'c': -.18, 's': -.18,
    'd': -.12, 'k': -.15, 'n': -.12, 'f': -.10, 'm': -.05,
    'j': .35, 'y': .35, 'z': .24, 'v': .19, 'w': .18,
    'r': .17, 'h': .11, 'l': .06, '0': .93,
}
# Common short spelling prefixes; these are not token identities.
SPELLING = {
    'et': -.56, 'en': -.22, 'em': -.21, 'er': -.17,
    'ed': -.17, 'es': -.13, 'at': -.37, 'al': .09,
    'id': .30, 'iv': .15, 'im': .14,
    'in': -.10, 'it': -.10, 'is': -.12,
    'on': .24, 'om': .30, 'ot': -.52, 'oc': -.09,
    'ow': .13, 'ou': -.10, 'ur': .15, 'ut': -.21,
    'up': -.17, 'ub': .16, 'st': -.09,
}
SHORT_VOWELS = {
    'o': (.88, .75, .43, .29),
    'u': (.68, .45, .27, 0.),
    'i': (.42, .20, .12, .07),
    'a': (.27, .12, .09, .03),
    'e': (-.06, -.12, -.14, -.16),
}


def spelling(text):
    text = text.lower().translate(EQUIVALENTS)
    return ''.join(c for c in unicodedata.normalize('NFD', text)
                   if unicodedata.category(c) != 'Mn')


def previous_strength(text):
    q = spelling(text).lstrip()
    if not q or q[-1].isspace():
        return 0.0
    if q.endswith('d'):
        n = len(q)
        strength = 1.5 if n <= 2 else 1.35 if n == 3 else 1.05 if n == 4 else .55
        if len(q) > 1:
            if q[-2] in 'nl':
                strength += .3
            elif q[-2] in 'ri':
                strength += .15
            elif q[-2] in 'ou':
                strength -= .2
        if text.endswith('د'):
            strength += .45
        return strength
    if q.endswith(('t', 'th')):
        return .16 if q.endswith('nt') else .075
    if q.endswith('ds'):
        return .20
    return 0.0


def continuation_response(text):
    if not text or text[0].isspace():
        return 0.0
    if text.startswith('.ts'):
        return -1.0  # TypeScript declaration suffix, as in .d.ts
    if text[:1].lower() in 'жž':
        return .8
    if text.startswith('ц'):
        return -.6
    if text.startswith('атель'):
        return -1.3  # Russian agent-noun ending
    if text.startswith('ان'):
        return -.35
    if text.startswith('گ'):
        return -1.15
    if text.startswith('ู'):
        return 1.7
    q = spelling(text)
    if not q:
        return 0.0
    first = q[0]
    value = ONSET.get(first, 0.0) + SPELLING.get(q[:2], 0.0)
    n = len(text)
    if first in SHORT_VOWELS and n <= 4:
        value += SHORT_VOWELS[first][n - 1]
    if q.startswith('erson'):
        value += .58
    if q.startswith(('tk', 'ts', 'tp')):
        value -= .72
    if text[0].lower() in 'ôōöøûūů':
        value += .25
    if text[0].lower() in 'ôō':
        value += 1.0
    if q in ('s', 'es', 'ing'):
        value = -.04
    elif q == 'able':
        value = -.28
    elif q == 'ation':
        value = -.14
    elif q == 'et':
        value = -1.0
    elif q == 'at':
        value = -.5
    elif q in ('st', 't'):
        value = -.75
    if text.isupper():
        value -= .05
    if text == "'":
        value = .15
    return value


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    text = prefix.token_strings[-1]
    strength = carry[1] if carry is not None and carry[0] == doc else 0.0
    value = strength * continuation_response(text)
    return (doc, previous_strength(text)), float(value)

"""Detect manner/means constructions, not the rest of the lexical variation.

'How' is strongest at a document's start or after learning/explanation
verbs, weaker in standalone questions, and suppressed in 'no matter how'.
'Through' contrasts passage/motion (negative) with accomplishment and
abstract-noun contexts (positive). Chinese manner/means words and the
quantity/modal words immediately following 'how' get smaller responses.
A short text tail supplies the preceding word and resets per document.
"""

import re

READS = ()
LEARNING = ('learn', 'understand', 'describ', 'demonstrat', 'illustrat', 'consider')
EXPLANATION = ('show', 'explain')
UNCERTAINTY = ('know', 'wonder', 'calculat', 'specif')
ACCOMPLISHMENT = ('achiev', 'accomplish', 'improv', 'enhanc', 'develop',
                  'strengthen', 'convey', 'express', 'build', 'learn')
ABSTRACT_NOUN_ENDINGS = ('tion', 'tions', 'ment', 'ments', 'ity', 'ities',
                        'ness', 'ship', 'ance', 'ence')
PASSAGE = {'pass', 'passes', 'passing', 'passed', 'trace', 'traces'}
MOTION = {'go', 'goes', 'going', 'gone', 'went', 'come', 'came', 'coming',
          'run', 'runs', 'running', 'walk', 'walks', 'walking',
          'travel', 'travels', 'traveling', 'flow', 'flows'}


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    first = carry is None or carry[0] != doc
    tail = '' if first else carry[1]
