    word = token.strip()
    lower = word.lower()
    match = re.search(r'([a-z]+)\s*$', tail.lower())
    prev = match[1] if match else ''
    value = 0.0

    if lower == 'how':
        value = 0.53 if word == 'how' else 0.30
        if not token.startswith(' '):
            value = 0.42 if word == 'how' else 0.38
        if first:
            value = 1.10 if word == 'how' else 0.98
        elif re.search(r'\bno\s+matter\s*$', tail.lower()):
            value = 0.0
        elif prev.startswith(LEARNING):
            value = 0.79
        elif prev.startswith(EXPLANATION):
            value = 0.66
        elif prev.startswith(UNCERTAINTY) or prev == 'sure':
            value = 0.33
        elif prev in {'about', 'on', 'of', 'in'}:
            value = 0.63
        elif prev in {'but', 'so', 'then'} or re.search(r'[.?!]\s*$', tail):
            value = 0.28
    elif lower == 'through':
        if prev in PASSAGE:
            value = -0.36
        elif prev in MOTION:
            value = -0.23
        elif prev.startswith(ACCOMPLISHMENT):
            value = 0.34
        elif prev.endswith(ABSTRACT_NOUN_ENDINGS):
            value = 0.19
        elif word == 'Through' and token.startswith(' '):
            value = 0.14
    elif word == '如何':
        value = 0.84 if first else 0.22
    elif word == '通过':
        value = 0.23
    elif word == '怎么':
        value = 0.10
    elif prev == 'how':
        if lower in {'many', 'much'}:
            value = 0.11
        elif lower in {'you', 'they', 'it', 'he', 'she', 'we', 'can', 'could'}:
            value = 0.08
    elif lower in {'can', 'could'} and re.search(r'\bhow\s+\w+\s*$', tail.lower()):
