    return (doc, (tail + token)[-100:]), value

"""Partial text-shape explanation of this layer-zero component.

Large positive responses occur on E5-prefixed UTF-8 fragments and selected
CJK encoding ranges, especially standalone 命, 倒, 副, 始 and 帝. Merged
words attenuate these character responses. Three known two-byte opening
fragments also get positive responses, before a character is complete.
This is an encoding/lexical pattern, not a unified semantic topic.
"""
READS = ()

# The tokenizer's first 256 entries are a permuted byte alphabet.
_PRINTABLE = list(range(33, 127)) + list(range(161, 173)) + list(range(174, 256))
_BYTES = _PRINTABLE + [b for b in range(256) if b not in _PRINTABLE]


def cjk_gain(c):
    # Life/command, reversal, deputy, beginning, emperor.
    if c in '命倒':
        return 0.88
    if c == '副':
        return 0.77
    if c == '始':
        return 0.59
    if c == '帝':
        return 0.65
    u = ord(c)
    if 0x5000 <= u < 0x5140 or 0x5440 <= u < 0x5480:
        return 0.19
    if 0x54C0 <= u < 0x5540 or 0x5580 <= u < 0x5680:
        return 0.18
    if 0x5740 <= u < 0x5900:
        return 0.12
    if 0x5940 <= u < 0x59C0:
        return 0.09
    if 0x59C0 <= u < 0x5B40:
        return 0.23
    if 0x5C80 <= u < 0x5D80 or 0x5E00 <= u < 0x5E40:
        return 0.12
    return 0.0


def token_gain(s):
    w = s.strip()
    anchors = sum((cjk_gain(c) for c in w if c in '命倒副始帝'), 0.0)
    broad = sum((cjk_gain(c) for c in w if c not in '命倒副始帝'), 0.0)
    if len(w) > 1:
        return (0.49 * anchors + 0.58 * broad) / len(w)
    return 0.98 * anchors + 0.89 * broad


# These tokenizer entries contain only two bytes, not a complete character:
# E5 91 opens characters such as 命, E5 89 such as 副, E5 A2 such as 墨.
_PARTIAL_E5 = {17401: 0x91, 20741: 0x89, 42144: 0xA2}


def step(carry, prefix, upstream):
    doc = int(prefix.document_ids[-1])
    token = int(prefix.token_ids[-1])
    value = token_gain(prefix.token_strings[-1])
    if token in _PARTIAL_E5:
        value = 0.53 if _PARTIAL_E5[token] == 0xA2 else 0.44
    if carry is not None and carry[0] == doc and carry[1] and token < 256:
        byte = _BYTES[token]
        if 0x80 <= byte < 0xC0:
            value = 1.3 if byte in (0x91, 0x92, 0x94) else 0.70
    # E5 alone and space+E5 are unfinished starts of U+5000–U+5FFF.
    return (doc, token in (161, 4891)), value

