"""Chinese word-initial characters (draft 2).

Fires on a Chinese character that opens a longer word, where the next character
completes it: 命 (命运, 命令), 倒 (倒下), 副 (副总), 始 (开始), 告 (告诉), 帝 (皇帝),
呼 (呼吸), 委 (委员), 娱 (娱乐)... Ordinary one-character function words (的, 了, 是)
stay near zero. Two-character words that are already complete and often used
(娱乐, 唯一, 值得) fire too. A small extra case: " of" after "kind"/"sort"/"way"
("kind of ...") fires weakly.

Values are typical activations read off a sample of training rows.
"""

READS = ()

# Chinese character (word-initial) -> typical activation
OPENERS = {
    "命": 0.9, "倒": 0.9, "副": 0.8, "始": 0.6, "帝": 0.6, "呼": 0.6,
    "委": 0.5, "勒": 0.4, "告": 0.4, "唐": 0.4, "奶": 0.35, "傅": 0.7,
    "假": 0.45, "借": 0.25, "值": 0.2, "唯": 0.5, "娱": 0.5,
}
# Whole words that are often used and fire on their own
WORDS = {
    "娱乐": 0.5, "唯一": 0.55, "值得": 0.55, "命令": 0.35, "颜值": 0.3,
    "女性": 0.25, "媒体": 0.3, "咖啡": 0.2, "婚姻": 0.5, "咨询": 0.45,
}
# Words that take "of" as a partitive: "kind of", "sort of", "way of"...
PARTITIVE_HEADS = {"kind", "sort", "way", "version", "direction", "process"}


def step(carry, prefix, upstream):
    tok = prefix.token_strings[-1]
    if tok in WORDS:
        return None, WORDS[tok]
    if tok in OPENERS:
        return None, OPENERS[tok]
    if tok == " of" and len(prefix.token_strings) > 1:
        if prefix.token_strings[-2].strip().lower() in PARTITIVE_HEADS:
            return None, 0.1
    return None, 0.0

programs.sol:
"""Detect short 'al' syllables, rather than every word containing those letters.

Short consonant+al fragments give a large negative response. Following letters,
capitalization, and consonant spelling change its strength. The response weakens
for common grammatical words and for -al/-ally suffixes after a longer stem.
Additional rules cover Cyrillic ал, Arabic ال, and Chinese salt characters.
Vowel counts are spelling-based proxies, not a pronunciation analysis. The
carried state is the last 40 letters of the unfinished word, reset by document.
"""
import re
import unicodedata

READS = ()
VOWELS = set('aeiou')
GRAMMATICAL = {'all', 'also', 'always', 'already', 'almost', 'although',
               'allow', 'allows', 'allowed', 'allowing', 'allowance'}
ONSETS = {'', 'b', 'c', 'd', 'f', 'g', 'h', 'k', 'm', 'p', 's',
          't', 'v', 'w', 'sc', 'th'}


def response(token, prior):
    body = token.strip()
    low = ''.join(c for c in unicodedata.normalize('NFD', body.lower())
                  if unicodedata.category(c) != 'Mn')
    if token.startswith('<'):
        return 0.0
    if 'ı' in body:
        return -0.05
    if any(c in body for c in '盐鹽咸'):
        return -2.35
    if 'ال' in low:
        if low == 'ال':
            return -0.5 if token[0].isspace() else -1.65 if prior else -1.35
        return -0.05
    if 'ал' in low:
        i = low.index('ал')
        tail = len(low) - i - 2
        base = -2.4 if len(prior) == 1 else -1.65
        return base / (1.0 + 0.7 * tail + 0.8 * i)
    if 'al' not in low:
        return -0.002
    i = low.index('al')
    onset = re.split('[^a-z]+', low[:i])[-1]
    tail = re.split('[^a-z]+', low[i + 2:])[0]
    continuation = bool(prior and token[0].isalpha() and i == len(onset))
    if low in GRAMMATICAL:
        return -0.55 if continuation and low == 'all' else 0.0
    if any(c in VOWELS for c in onset):
        return -0.20 if len(low) <= 4 else -0.025
    if len(body) <= 3 and low != body.lower() and 'al' in low:
        return -1.3
    if onset not in ONSETS:
        return -0.05
    if continuation and low in {'al', 'ale', 'als', 'ales', 'ally'}:
        # A longer, vowel-rich stem tends to make al an unstressed suffix.
        stem = prior.lower()
        value = -2.65 + 0.22 * min(4, sum(c in VOWELS for c in stem))
        value += 0.07 * min(8, len(stem))
        last = stem[-1]
        if last == 'r':
            value += 0.65
        elif last == 'l':
            value -= 0.35
        elif last in 'szhg':
            value -= 0.6
        else:
            value += 0.2
        if stem.endswith(('ion', 'ment')):
            value += 0.7
        if low in {'als', 'ales'}:
            value += 0.95
        elif low == 'ally':
            value += 1.1
        if prior[0].isupper():
            value -= 0.25
        return float(value)
    if low.startswith(('along', 'align', 'alog', 'altern')):
        return -0.1
    if onset == 'c' and tail.startswith('ori'):
        return -1.6  # calorie family
    if onset == 'b' and tail.startswith('anc'):
        return -1.5  # balance family
    if not onset and tail.startswith(('ph', 'ert', 'ex')):
        return -0.6
    if not onset and tail.startswith('k'):
        return -0.8
    if not tail:
        if not onset:
            value = -1.72 if token[0].isspace() else -2.45
        elif onset == 'v':
            value = -1.5
        elif onset in {'g', 'h', 's'}:
            value = -3.8
        elif onset in {'b', 'f', 'k', 'm', 'p', 'th'}:
            value = -3.2
        else:
            value = -2.25
        if body[0].isupper():
            value -= 0.25
    elif tail.startswith('l'):
        if not onset:
            value = -0.6 if tail == 'l' else -1.2
        elif onset in {'b', 'f', 't', 'w'}:
            value = -0.7
        elif onset == 'c':
            value = 0.0
        else:
            value = -1.4
    elif tail.startswith('e'):
        if not onset or onset in {'d', 'p', 'v'}:
            value = -2.0
        elif onset == 'h':
            value = -3.5
        elif onset in {'t', 'sc', 'm'}:
            value = -1.0
        else:
            value = -1.3
        if len(tail) > 1:
            tail = tail[1:]
    else:
        if onset == 'v' and tail.startswith(('u', 'id')):
            return 0.0
        if onset in {'f', 't'}:
            return -0.05
        value = -1.5 if onset in {'s', 'g'} else -0.8 if onset else -1.2
        if not onset and len(tail) <= 2:
            value = -1.25 if tail[0] in 'st' else -2.25
    value /= 1.0 + 0.4 * max(0, len(tail) - 2)
    if continuation:
        value *= 0.8 ** min(4, sum(c in VOWELS for c in prior.lower()))
    return float(value)


def step(carry, prefix, upstream):
    document = prefix.document_ids[-1]
    prior = '' if carry is None or carry[0] != document else carry[1]
    token = prefix.token_strings[-1]
    value = response(token, prior)
    match = re.search(r'[^\W\d_]+$', token)
    fragment = ''
    if match and not token.startswith('<|'):
        fragment = ((prior if match.start() == 0 else '') + match.group())[-40:]
    return (document, fragment), float(value)

"""Approximate a spelling-boundary interaction.

A word fragment beginning with h gets a large negative response when the
previous token ends in l or n. Vowel+r/l fragments get a smaller negative
response; a followed by a stop or sibilant gets a positive one. Long fragments
weaken these joins. Short h fragments also have a smaller negative response
after r, i, m, or the endings le/ne/ad/at/it. Other r/t/v/z continuations
are negative after l/n, while st- is positive. The rules also use analogous
Cyrillic letters. Small fixed responses cover chat/tool
delimiters. Other tokens predict zero; token-specific background variation
is deliberately left unexplained.
"""
import unicodedata

READS = ()
CYRILLIC = str.maketrans({
    'а': 'a', 'е': 'e', 'ё': 'e', 'и': 'i', 'о': 'o', 'у': 'u',
    'л': 'l', 'н': 'n', 'р': 'r', 'х': 'h', 'с': 's', 'г': 'g',
    'б': 'b', 'к': 'k', 'ф': 'f', 'т': 't', 'в': 'v', 'з': 'z',
    'ь': '',
})
MARKERS = {
    '<tool_call>': -0.164, '</tool_call>': -0.068,
    '</think>': -0.191, '<|im_start|>': 0.043,
    '<|im_end|>': -0.033,
}


def spelling(text):
    return ''.join(c for c in unicodedata.normalize('NFD', text.lower())
                   if not unicodedata.combining(c)).translate(CYRILLIC)


def step(carry, prefix, upstream):
    text = prefix.token_strings[-1]
    doc = prefix.document_ids[-1]
    previous = carry[1] if carry is not None and carry[0] == doc else ''
    prev, s = spelling(previous), spelling(text)
    ending = prev[-1:]
    value = MARKERS.get(text, 0.0)
    if s.startswith('h'):
        if ending in ('l', 'n'):
            value = -1.7 if ending == 'l' else -1.2
            if text.isupper():
                value *= 0.7
            if len(s) == 4:
                value *= 0.34
            elif len(s) > 4:
                value *= 0.18
        elif ending in ('r', 'i', 'm'):
            value = -0.3 if len(s) <= 3 else -0.08
        elif prev[-2:] in ('le', 'ne', 'ad', 'at', 'it'):
            value = -0.35 if len(s) <= 3 else -0.08
    elif ending in ('l', 'n') and 1 < len(s) <= 9:
        if s[:2] in ('ir', 'or', 'ur', 'il', 'ul'):
            value = -0.46 if ending == 'l' else -0.3
        elif s[0] in 'aeiou' and s[1] in 'rlh':
            value = -0.24 if ending == 'l' else -0.16
        elif s[:2] in ('ab', 'af', 'ag', 'ak', 'as'):
            value = 0.18 if ending == 'l' else 0.14
        elif s.startswith('st'):
            value = 0.2 if ending == 'l' else 0.15
        elif s[0] == 'r':
            value = -0.45 if ending == 'l' else -0.25
        elif s[0] in 'tvz':
            value = -0.2 if ending == 'l' else -0.07
        elif s.startswith('u'):
            value = -0.13 if ending == 'l' else -0.03
        if len(s) > 3:
            value *= 0.75 if len(s) <= 5 else 0.35
    if text in MARKERS:
        value = MARKERS[text]
    elif ending in ('l', 'n') and len(prev.strip()) > 5:
        value *= 0.55
    return (doc, text), float(value)

programs.luna:
"""Mark words about changes, variation, and dependence on conditions.

The strongest readable cue is language such as “depending on”; related verbs
like vary, differ, adjust, and modify are weaker cues. This is a lexical sketch,
not a claim to recover all of the component's context-sensitive activations.
"""

READS = ()

def _word(text):
    """The alphabetic word currently being typed, including split word pieces."""
    chars = []
    for char in reversed(text):
        if char.isalpha():
            chars.append(char.casefold())
        else:
            break
    return "".join(reversed(chars))


def _has(text, roots):
    return any(root in text for root in roots)


def step(carry, prefix, upstream):
    token = prefix.token_strings[-1]
    doc = prefix.document_ids[-1]
    old_doc, history = carry if carry is not None else (doc, ())
    if doc != old_doc:
        history = ()

    recent = "".join(history)
    word = _word(recent + token)
    value = 0.0065

    if word.startswith("depend"):
        value = 3.0 if word.startswith("depending") else 2.2
    elif word.startswith(("contingent", "according")):
        value = 1.0
    elif word.startswith(("based", "subject", "condition")):
        value = 0.7
    elif word.startswith(("vary", "fluctuat")):
        value = 1.8
    elif word.startswith("differ"):
        value = 1.15
    elif word.startswith("change"):
        value = 1.0
    elif word.startswith(("adjust", "alter", "modify", "regulat", "adapt")):
        value = 1.0
    elif word.startswith(("affect", "influenc", "control", "determin")):
        value = 0.8
    elif word.startswith(("specific", "particular", "various", "diverse")):
        value = 0.8
    elif word.startswith(("flexib", "effect", "impact", "revision", "revise", "shift")):
        value = 0.65

    prior = recent.casefold()
    if word == "on" and _has(prior, ("depend",)):
        value = 3.0
    elif word == "on" and _has(prior, ("based", "effect", "impact")):
        value = max(value, 0.9)
    elif word == "by" and _has(prior, ("determin", "regulat", "govern", "control")):
        value = 1.0
    elif word == "in" and _has(prior, ("vary", "differ", "change")):
        value = 1.2
    elif word == "to" and _has(prior, ("adjust", "adapt", "modify")):
        value = 0.8

    carry = (doc, (history + (token,))[-8:])
    return carry, float(value)

programs.sol:
"""Approximate lexical freshness, rather than a judgment that food is fresh.

The strongest cues are fresh and Chinese 鲜/鮮. Their word compounds, the
pieces fres/resh, refresh, tenderness, novelty and preserved food are weaker
cues. One-token memory recognizes fresh split across a token boundary and
its suffixes. Other small, unrelated lexical effects are left at zero.
