# Compounds distinguish literal freshness from vividness and seafood.
CHINESE_FRESHNESS = {
    '鲜': 8.3, '鮮': 6.7,
    '新鲜': 5.8, '新鮮': 5.8,
    '生鲜': 3.6, '鲜活': 3.6, '鲜艳': 3.0,
    '保鲜': 2.0, '鲜明': 1.7, '鲜花': 1.6,
    '海鲜': 1.1, '海鮮': 1.1, '鲜血': 1.2,
    '嫩': 1.2, '新颖': 1.4, '新穎': 1.4, '清新': 0.8,
