    doc = prefix.document_ids[-1]
    previous = carry[1] if carry is not None and carry[0] == doc else ''
    raw = prefix.token_strings[-1]
    token = raw.strip()
    word = token.lower().lstrip('._')
    value = 0.0
    if word == 'fresh':
        value = 4.45 if token.islower() else 4.8
    elif word == 'freshly':
        value = 3.4
    elif word == 'freshness':
        value = 2.9
    elif word in {'freshmen', 'freshman', 'freshwater'}:
        value = 1.9 if word == 'freshmen' else 1.3
    elif word == 'fres':
        value = 2.0 if token.islower() else 1.25
    elif word == 'resh':
        value = 2.75 if token.isupper() else 1.1
        if previous.endswith('f'):
            value = 2.5
        elif previous.endswith('th'):
            value = 2.0
    elif word == 'refresh':
        value = 0.55
    elif word in {'refreshed', 'refreshing'}:
        value = 0.2
    elif token in CHINESE_FRESHNESS:
        value = CHINESE_FRESHNESS[token]
    elif word in {'lush', 'pristine', 'grocery', 'groceries'}:
        value = 1.0
    elif word in {'canned', 'shelf', 'preservation', 'dehyde'}:
        value = 0.5
    elif word in {'stale', 'frozen', 'preserved', 'refrigerator', 'latest'}:
        value = 0.35
    if raw and not raw[0].isspace():
        if previous.endswith('fresh') and word in {'man', 'men', 'ly', 'water'}:
            value = {'man': 1.5, 'men': 1.8, 'ly': 2.8, 'water': 0.9}[word]
        elif previous.endswith('fres') and word in {'her', 'hest', 'co', 'coes'}:
            value = 1.2 if word in {'her', 'hest'} else 0.8
