programs.sol:
"""Negative pulses for a full stop joined to more punctuation in one token.

A lone period is quiet. A following newline gives a small pulse; a quote
or programming symbol gives a larger one. Ellipses and abbreviations
soften it. Newline pulses are stronger near document starts and in
short-line layouts. Ordinary words and tokens without a full stop stay near zero.
"""
import re

READS = ()

# The character immediately after the full stop sets the pulse's size.
PUNCTUATION_STRENGTH = {
    ',，': 3.7,
    ';；': 3.2,
    ':：': 3.8,
    '_': 3.1,
    '\\': 2.55,
    '/': 4.7,
    '-–—': 4.1,
    '*^+%#=|': 4.3,
    ')]}）】': 3.7,
    '([{（【': 2.2,
    '<>': 2.8,
    '!?！？&`': 3.4,
    '$': 1.7,
    '"“”': 1.4,
    "'‘’": 1.9,
}
QUOTES = '"“”\'‘’'
COMMON_ABBREVIATIONS = {'etc', 'jr', 'sr', 'inc'}


def punctuation_pulse(token, tail, position, line_density):
    text = token.lstrip(' ')
    if any(c.isalnum() for c in text):
        return -0.002
    dot = next((i for i, c in enumerate(text) if c in '.。'), -1)
    if dot < 0:
        return -0.002
    before, after = text[:dot], text[dot + 1:]
    repeats = 1
    while after.startswith(text[dot]):
        repeats += 1
        after = after[1:]
    if text[dot] == '。' and repeats > 1:
        return -0.6 if repeats == 2 else -0.35
    if not after:
        return -0.25 if repeats == 2 or repeats >= 4 else -0.002
    if after[0] in '\r\n':
        if repeats > 1:
            return -0.28 if repeats == 2 else 0.03
        if before:
            return -0.3
        value = -0.28 - 0.68 / (1 + position / 20) - 0.37 * line_density
        value += 0.09 if after.count('\n') > 1 else 0.0
        if position == 0:
            value = -0.65 if after.count('\n') == 1 else -0.49
        return value - (0.35 if after.startswith('\r') else 0.0)
    strength = next((v for chars, v in PUNCTUATION_STRENGTH.items()
                     if after[0] in chars), 2.7)
    if after.startswith('__'):
        strength = 2.05
    if after[0] in ',)':
        match = re.search(r'([A-Za-z]+)$', tail)
        word = match.group(1).lower() if match else ''
        if re.search(r'(?:e\.g|i\.e)$', tail.lower()):
            strength = 1.4
        elif re.search(r'\.[A-Za-z]{1,2}$', tail):
            strength = 1.9
        elif word in COMMON_ABBREVIATIONS:
            strength = 1.9 if after[0] == ',' else 2.3
        elif tail.lower().endswith('et al'):
            strength = 2.6
    compound_quote = after[0] in QUOTES and any(c in after[1:] for c in ',;):')
    if compound_quote:
        strength = 2.45 if ')' in after else 2.9
    if '\n' in after:
        strength *= 0.9 if compound_quote else (0.70 if after[0] in QUOTES else 0.48)
    if before or token.startswith(' '):
        strength *= 0.65 if any(c in QUOTES for c in before) else 0.8
    if repeats > 1:
        strength *= 0.65 if repeats == 2 and not before else 0.22
    return -strength


def step(carry, prefix, upstream):
    document = prefix.document_ids[-1]
    if carry is None or carry[0] != document:
        carry = (document, 0, 0, 0, '')
    _, position, characters, newlines, tail = carry
    token = prefix.token_strings[-1]
    # Many line breaks in little text indicate a short-line layout.
    line_density = min(1.0, 30 * newlines / (characters + 100))
    value = punctuation_pulse(token, tail, position, line_density)
    carry = (document, position + 1, characters + len(token),
             newlines + token.count('\n'), (tail + token)[-64:])
    return carry, float(value)

programs.luna:
"""Approximate a punctuation-boundary response from the current token.

It predicts negative values for a period followed by whitespace, selected
punctuation, or an uppercase letter. It also recognizes a Chinese full stop
before a quote or line break, and common colon-plus or colon-slash punctuation pairs.
"""

READS = ()


def step(carry, prefix, upstream):
    token = prefix.token_strings[-1]

    # Sentence-ending full stops that share a token with a line break.
    if "." in token:
        dot = token.rfind(".")
        following = token[dot + 1 :]
        if not following:
            return None, 0.0
        char = following[0]
        if char.isspace():
            return None, -0.44
        if char == ",":
            return None, -2.25
        if char == ";":
            return None, -3.0
        if char == "_":
            return None, -3.1
        if char == ".":
            return None, -0.35
        if char in "\\/":
            return None, -2.7
        if char == "(":
            return None, -2.2
        if char == ")":
            return None, -2.9
        if char == "[":
            return None, -2.6
        if char in "]}":
            return None, -2.6
        if char in "\u201c\u201d\u2018\u2019\"'":
            return None, -1.6
        if char.isupper():
            return None, -0.16
        return None, 0.0

    # Chinese full stops can also share a token with a line break or quote.
    if "。" in token:
        stop = token.rfind("。"); following = token[stop + 1 :]
        if following.startswith(("\n", "\r")):
            return None, -0.54
        if following.startswith(("”", "’", "\"", "'")):
            return None, -1.5

    # Punctuation pairs used as code operators or path/URL separators.
    if token.endswith(":+"):
        return None, -0.81
    if token.endswith((":/", ":\\")):
        return None, -0.62
    if token.endswith("://"):
        return None, -0.27

    return None, 0.0

programs.sol:
"""Detect ball words, ball sports, and weaker spherical/ball-like spellings.

Most tokens contribute zero. Literal 'ball' fragments contribute about -6,
with a smaller response for space-prefixed plural 'balls'. Sport names,
spherical objects, bird words, and near-spellings have weaker responses.
Matching is on the current token, not the complete word: 'Ball' at the
start of 'Ballot' therefore fires too. No future text is needed.
"""
READS = ()

BALL_SPORTS = {'football', 'baseball', 'volleyball', 'softball', 'handball'}
OTHER_SPORTS = {'tennis', 'hockey', 'golf', 'cricket', 'soccer', 'rugby'}
SPHERICAL_OBJECTS = {'sphere', 'spheres', 'spherical', 'marble', 'marbles'}
BALL_IN_CHINESE = {'足球', '羽毛球', '乒乓球'}


def response(token):
    word = token.strip().lstrip('-')
    lower = word.lower()
    spaced = token.startswith(' ')
    if lower in {'ball', 'balls'}:
        value = -5.0 if lower == 'balls' and spaced else -6.1
        if word.istitle() and spaced:
            value -= 0.25
        return value
    if lower == 'basketball':
        return -3.0 if word.istitle() else -2.4
    if lower in BALL_SPORTS:
        return -1.35 if lower == 'football' and not spaced else -1.95
    if lower in OTHER_SPORTS:
        return -1.05 if lower in {'rugby', 'soccer'} else -0.8
    if lower == 'chess':
        return -0.6
    if lower == 'sports':
        return -0.3
    if lower in {'ballot', 'ballots'}:
        return -2.1
    if lower.startswith('ball') or lower.endswith('ball'):
        return -0.5 if lower == 'ballpark' else -1.2
    if lower in SPHERICAL_OBJECTS:
        return -0.8
    if word == '球':
        return -4.3
    if word == 'ボール':
        return -3.8
    if word == '篮球':
        return -2.7
    if word in BALL_IN_CHINESE:
        return -1.9
    if word in {'球场', '球迷', '眼球'}:
        return -1.0
    if lower in {'bird', 'birds'}:
        return -0.7
    # Weaker spelling echoes: bal, bell, fall, and lowercase all fragments.
    if lower == 'bal':
        return -1.0
    if lower in {'bell', 'fall', 'falls'}:
        return -0.3 if spaced and word.islower() else -0.5
    if word == 'all':
        return -0.1 if spaced else -0.6
    if not spaced and word in {'alls', 'alled', 'alle', 'aller', 'allis'}:
        return -1.0 if word in {'alls', 'alled'} else -0.55
    return 0.0


def step(carry, prefix, upstream):
    return None, response(prefix.token_strings[-1])

