    (2.4, {'督促'}),                         # urge
    (2.0, {'阻碍'}),                         # impede
    (1.3, {'加快', '鼓励', '有助于', '有利于', '助力',
           '扶持', '抑制', '抑', 'förder'}),   # accelerate, assist, inhibit
    (1.0, {'catal', 'catalyst', 'hinder', 'hind', 'enabling',
           '加速', '刺激', '便于', '有助'}),
    (0.75, {'stim', 'stimulus', 'stimuli', 'encour', 'ilit', 'facil',
            '推广', '引导', '指导', '激励', '激发', '倡导', '催'}),
    (0.6, {'enable', 'enables', 'aid', 'bolster', 'boost', 'enhance',
           'retard', '助', '推'}),
