def lexical(word):
    if word == '<|endoftext|>':
        return 2.56
    if word.startswith('促进'):
        return 6.0
    if word == '促':
        return 4.8
    if any(root in word for root in ('推动', '推動')):
        return 2.1
    if any(root in word for root in ('推进', '推進')):
        return 1.6
    if word.startswith('facilitat'):
        return 4.0 if word.endswith('ing') else 3.3
    if word == 'facilit':
        return 2.7
    if word in {'promote', 'promotes', 'promoting'}:
        return 2.25
    if word in {'promotion', 'promoted', 'promoters'}:
        return 1.4
    if word in {'prom', '-prom', 'promoter'}:
        return 1.0
    if word.startswith('encourag'):
        return 1.2
    if word.startswith('foster'):
        return 2.1
    if word.startswith('inhib'):
        return 1.1
    if word.startswith('stimulat'):
        return 0.7 if word.endswith('ion') else 1.3
    if word.startswith(('prohibit', 'regulat')):
        return 0.6
    for value, words in ACTION_GROUPS:
        if word in words:
            return value
    return 0.0


def step(carry, prefix, upstream):
    token = prefix.token_strings[-1]
    doc = prefix.document_ids[-1]
    previous = '' if carry is None or carry[0] != doc else carry[1]
    word = token.strip().lower()
    value = lexical(word)
    if word == 'fost':
        value = 1.2
    elif word == 'fac':
        value = 0.25 if token == ' fac' else 1.0
    elif token.strip() == 'Foster':
        value = 0.8                 # also a proper name
    if word == 'of':
        if previous in {'promotion', 'stimulation', 'inhibition'}:
            value = 1.0
        elif previous in {'inhibitor', 'inhibitors', 'regulation',
                          'regulator', 'aid', 'advocate'}:
            value = 0.5
    if word == 'for' and previous in {
        'allow', 'allows', 'allowing', 'catalyst', 'advocate', 'advocates',
    }:
        value = 0.55
    if not token[:1].isspace():
        if previous == 'facilit' and word in {
            'ation', 'ations', 'ator', 'ators',
        }:
            value = 2.1 if word.startswith('ation') else 2.7
        elif previous in {'prom', '-prom'} and word in {
            'ote', 'otes', 'oting', 'oted',
        }:
            value = 2.3
        elif previous in {'fost', 'foster'} and word in {
            'er', 'ers', 'ed', 'ing',
        }:
            value = 2.1
        elif previous == 'inhib' and word in {
            'iting', 'itory', 'itor', 'itors',
        }:
            value = 1.1
        elif previous == 'fac' and word.startswith('ilitat'):
            value = 4.0
        elif previous in {'推动', '推動', '促进'} and word == '了':
            value = 1.7
        elif previous == '促' and word in {'进', '進'}:
            value = 2.4
    return (doc, word), value

"""Detect the spelling 'ar', especially at the end of a short token.

Long words and extra letters after ar weaken the response. Frequent
short ar forms and ear spellings also have lower gains. A small rolling
count of Spanish/Portuguese function words reduces the response to ar
endings in Romance-language text. Cyrillic ар and Arabic ار are handled
as analogous written endings. This is a spelling approximation, not a
full account of lexical meanings or preceding-word effects.
"""
import re

READS = ()
ROMANCE_CUES = frozenset('''
el la los las del al en por para que una con más pero como são não uma
um dos das do da os em com ao pelo pela você porque
'''.split())
COMMON_AR_FORMS = frozenset({'bar', 'car', 'par', 'war', 'var', 'char'})
WEAK_EAR_FORMS = frozenset({
    'year', 'clear', 'appear', 'unclear', 'nuclear', 'nonlinear',
})


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    recent = carry[1] if carry is not None and carry[0] == doc else ()
    token = prefix.token_strings[-1]
    spaced = token[:1].isspace()
    word = re.sub(r'^[\W_]+', '', token.strip()).lower()
    value = 0.0
    if word.endswith(('ar', 'ars')):
        plural = word.endswith('ars')
        stem = word[:-1] if plural else word
        n = len(stem)
        value = (3.5 if n <= 4 else 1.3 if n == 5 else
                 0.7 if n == 6 else 0.3)
        if n >= 5 and not spaced:
            value += 0.5
        if stem in COMMON_AR_FORMS:
            value = 1.8
        elif stem in {'mar', 'har'}:
            value = 2.7
        elif stem == 'ular':
            value = 1.9
        elif stem in {'solar', 'polar', 'stellar', 'olar', 'ellar'}:
            value = 2.8
        if stem.endswith('ear'):
            value = 2.7 if stem == 'ear' else 1.2
            if stem in WEAK_EAR_FORMS:
                value = 0.05
        if stem == 'sugar':
            value = 0.15
        if plural:
            value *= 0.72
        if n <= 4:
            damp = (1.0, 0.76, 0.61, 0.5)[min(sum(recent), 3)]
            value *= (0.5 + 0.5 * damp) if spaced else damp
    elif word.startswith('ar') and len(word) <= 5:
        value = 0.75
        if word[2:] in {'t', 'd', 'en', 'ea', 'eas', 'ray', 'ch', 'gs'}:
            value = 0.08
        elif word == 'are':
            value = 0.0 if spaced else 0.5
    elif 'ar' in word:
        value = 0.08
        if word in {'variable', 'variables', 'binary', 'carbon', 'parser'}:
            value = 0.7
        elif word.startswith('starr'):
            value = 2.0
    elif word.endswith('ар'):
        value = 2.0
    elif word.endswith('ار'):
        value = 1.45
    recent = (recent + (int(word in ROMANCE_CUES),))[-24:]
    return (doc, recent), float(value)

programs.haiku:
"""Negative activation on words that name a person, used to address someone or to refer to
a particular person by kinship, age, gender, friendship or role: 先生, 老师, 同志, 大哥, 姐,
爷, さん, 様, 君, 大家, sir, friend, doctor, guys, folks.

The program predicts a negative value on such words and 0 everywhere else:
  - polite address and honorifics (先生, 老师, 同志, 小姐, 大哥, さん, 様, 君): about -3;
  - a short word ending in a senior-kin character (姐 哥 爷 爸 兄 叔 姨 嫂 舅): about -2.5;
  - other kin, friend and role words (弟 妹 妈 爹 娘 婆 伯 父 友 公 老板 医生 教授 大家 们,
    and titles such as 总理 校长 院士): about -1;
  - English person words in running text (friend, brother, sister, doctor, colleague, uncle,
    dad, guys, folks, lady, gentleman, girlfriend): about -0.7;
  - weaker English titles and roles (teacher, officer, professor, sir, dear, husband): -0.3.
Ordinary nouns such as 人, man, woman, student, child are 0. A word's ending counts only for
words of up to two characters, so 办公 and 墨西哥 don't match.
"""

READS = ()

HONORIFIC = {
    "先生", "老师", "老師", "同志", "小姐", "大哥", "大爷", "大叔", "叔叔", "阿姨", "女士",
    "爷爷", "奶奶", "同学", "同學", "主席", "님", "さま", "様", "お客様", "くん",
}
SENIOR_KIN = set("姐爷爸哥兄叔姨嫂舅")
KIN_OR_ROLE = set("弟妹妈爹娘婆伯翁父友君郎仔傅")
PERSON = {
    "妹子", "医生", "医师", "老板", "主任", "女神", "大人", "老人", "大家", "们", "們",
    "同学们", "朋友们", "各位", "同事", "男生", "女生", "主播", "小编", "宝宝", "老公", "公",
    "男友", "女友", "网友", "朋友", "教授", "博士", "大师", "院士", "将军", "道士", "法师",
    "董事长", "总理", "秘书长", "校长", "司令", "院长", "部长", "市长", "厅长", "局长",
    "经理", "总经理", "总书记", "律师", "法官", "警察", "教练", "领导", "干部", "书记",
    "氏", "小朋友", "小姐姐", "媽媽", "老头", "老乡", "姊", "大佬", "爺", "嘉宾", "公主",
    "女王", "丈夫", "子弟", "真人", "讲师",
}
ENGLISH = {
    "friend", "friends", "brother", "brothers", "sister", "sisters", "doctor", "doctors",
    "colleague", "colleagues", "cousin", "uncle", "aunt", "dad", "guys", "folks", "lady",
    "ladies", "gentleman", "gentlemen", "classmates", "comrades", "girlfriend", "boyfriend",
    "grandmother", "grandfather", "dude", "nephew", "niece", "granny", "chairman", "boss",
    "buddy",
}
ENGLISH_WEAK = {
    "officer", "officers", "professor", "professors", "teacher", "teachers", "husband",
    "priest", "soldier", "sir", "dear", "guy", "lady", "bro", "father",
}

def is_cjk(s):
    return bool(s) and all("一" <= c <= "鿿" for c in s)

def step(carry, prefix, upstream):
    raw = prefix.token_strings[-1].strip()
    lower = raw.lower()
    if raw in HONORIFIC or raw.startswith(("さん", "ちゃん")) or raw.endswith(("先生", "老师")):
        return carry, -3.0
    if raw in PERSON:
        return carry, -1.0
    if is_cjk(raw) and len(raw) <= 2:
        if raw[-1] in SENIOR_KIN:
            return carry, -2.5
        if raw[-1] in KIN_OR_ROLE:
            return carry, -1.0
        return carry, 0.0
    if lower in ENGLISH:
        return carry, -0.7
    if lower in ENGLISH_WEAK:
        return carry, -0.3
    return carry, 0.0

programs.sol:
"""Opening brackets and braces, calibrated by their grammatical surroundings.

Quotes or operators fused to an opener give a large positive value; bare
openers, empty pairs and line-breaking block starts give smaller values.
LaTeX command classes change the response to a bare brace. Other tokens
have a near-zero baseline. Keep only recent text, resetting at documents.
"""
import re

READS = ()
TEXT_OR_ENV = {'text', 'textrm', 'mathrm', 'operatorname', 'begin', 'end'}
FONTS = {'mathcal', 'mathbf', 'mathsf', 'mathit', 'mathscr'}
ACCENTS = {'hat', 'widehat', 'vec', 'bar', 'overline', 'dot', 'tilde'}


def activation(text, previous, recent):
    s = text.lstrip()
    spaced = text.startswith(' ')
    prev = previous.strip()
    match = re.search(r'\\([A-Za-z]+)$', recent)
    command = match.group(1) if match else ''

    if s.startswith('['):
        tail = s[1:]
        if not tail or tail.isspace():
            return 1.00 if spaced else 0.74
        if tail.startswith(']'):
            return 0.10
        if tail[0] in '\"\'':
            return 2.92 if spaced else 2.05
        if tail[0].isalpha():
            return 2.18
        if tail.startswith('\\'):
            return 1.78
        if tail.startswith(('{', '[')):
            return 4.49 if any(c in tail for c in '\"\'') else 1.77
        if tail.startswith((',', ':')):
            return 2.03
        if tail.startswith(('...', '…')):
            return 0.65 if ']' in tail else 2.70
        if tail.startswith('/'):
            return 1.37
        return 3.34 if spaced else 2.98

    if s.startswith('{'):
        tail = s[1:]
        if not tail:
            if spaced:
                if prev.endswith('import'):
                    return 0.0
                if command:
                    return 0.46
                return 0.90 if prev.endswith(('=', ':', ',', '=>')) else 1.23
            if command in TEXT_OR_ENV:
                return -0.25
            if command.endswith('frac') or command in FONTS:
                return 0.17
            if command in ACCENTS or command in {'sqrt', 'mathbb', 'mathfrak'}:
                return 0.45
            if command in {'ref', 'eqref', 'label'}:
                return 0.82
            if command in {'cite', 'citep', 'citet'}:
                return 2.48
            if command:
                return 0.75
            return -0.10 if prev.endswith(('^', '_')) else 1.23
        if tail[0] in '\"\'':
            return 3.69 if spaced else 3.58
        if tail.startswith('\\'):
            if command in TEXT_OR_ENV | FONTS or command.endswith('frac'):
                return 1.20
            if command in {'hat', 'widehat', 'boldsymbol'} or prev.endswith(('^', '_')):
                return 1.20
            return 1.59 if command else 2.22
        if tail.startswith('}'):
            return 0.82
        if tail.startswith('{'):
            return 1.81
        if '\n' in tail or '\r' in tail:
            if '\r' in tail:
                return 1.55 if spaced else 2.13
            if tail.count('\n') > 1:
                return 1.68 if spaced else 1.94
            return 1.32 if spaced else 1.61
        if tail[0].isalpha():
            return 3.91 if len(tail) > 1 else 1.64
        return 3.30 if spaced else 3.03

    if s.startswith(('_{', '^{')):
        return 1.51 if s.endswith('-') else (0.38 if s[0] == '^' else 0.14)
    if '{' in s and s[:s.index('{')].endswith(')'):
        return 1.46 if '\n' in s else 1.12
    if s.startswith(('({', '={', '([', '=[')):
        tail = s[2:]
        if not tail or tail.isspace() or tail[0] in '}]':
            return 0.17 if s[1] == '[' else (-0.09 if s[0] == '=' else 0.41)
        return 2.17 if s[1] == '[' else 2.90
    if s.startswith(('},{', '}.{', '.[', '::{', '::<')):
        return -0.92
    if s.startswith(('}{', '}_{')):
        return -0.20
    if s.startswith(('":{', '":[{', '":["')):
        return 2.90
    if s.startswith('('):
        if s.startswith(('(-', '(+', '(*')):
            return 1.01 if spaced else 0.71
        if s.startswith('(('):
            return 1.42 if spaced else 1.13
        if spaced and len(s) > 1 and s[1] in '\"\'“`':
            return 0.76
    if s.startswith('<') and len(s) > 1 and s[1].isalpha():
        if s[1].isupper():
            return 0.87
        if not s.startswith(('<tool_', '<think')):
            return 0.69
    return 0.0


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    recent, previous = ('', '') if carry is None or carry[0] != doc else carry[1:]
    text = prefix.token_strings[-1]
    value = activation(text, previous, recent)
    return (doc, (recent + text)[-64:], text), value

programs.luna:
"""Give a positive pulse when a bracketed expression or object begins.

Opening curly braces and square brackets are the clearest triggers. A
curly brace that also opens a quoted-key object gets a larger pulse.
"""
READS = ()


def step(carry, prefix, upstream):
    token = prefix.token_strings[-1]
    text = token.lstrip()

    if text.startswith('{'):
        if text.startswith('{"') or text.startswith("{'"):
            return None, 3.7
        if text.startswith('{\\'):
            return None, 1.5 if token.lstrip() == token else 2.2
        if text.startswith('{\n') or text.startswith('{\r'):
            return None, 2.3 if token.lstrip() == token else 1.3
        return None, 1.0

    if text.startswith('['):
        if len(text) > 1 and not text[1].isspace():
            return None, 2.1
        return None, 0.8

    return None, 0.0

programs.sol:
"""Detect slash separators and a TeX numerator/denominator boundary.

Separate ASCII/fullwidth slashes fire strongly, more after words than numbers.
Fusing a slash to punctuation usually weakens it; attached words often give
a small negative. Combinations such as //, /*, and </ are suppressed.
Mathematical slash glyphs give weaker positives. For }{, a nearby frac{ is a
fraction cue, strongest with a short, simple numerator. Other tokens get a
near-zero background; their small, word-specific responses are not modeled.
"""
READS = ()


def step(carry, prefix, upstream):
    s = prefix.token_strings[-1].replace("／", "/")
    if s in ('∕', '⁄'):
        return None, 1.0 if s == '∕' else 0.72
    if s == '}{':
        # A bounded lookback for the numerator of a TeX fraction.
        recent = ''.join(
            prefix.token_strings[i]
            for i in range(max(0, prefix.position - 32), prefix.position + 1)
            if prefix.document_ids[i] == prefix.document_ids[-1])
        start = recent.rfind('frac{')
        if start >= 0:
            numerator = recent[start + 5:-2].strip()
            simple = len(numerator) <= 4 and not any(
                c in numerator for c in '\\_{}+-')
            return None, 0.49 if simple else 0.25
        return None, 0.04
    if '/' not in s:
        return None, 0.0012
    previous = ''
    if (prefix.position > 0 and
            prefix.document_ids[-1] == prefix.document_ids[-2]):
        previous = prefix.token_strings[-2]
    last = previous[-1:]
    clean = s.strip()

    if clean == '/' and '\n' not in s:
        if s.startswith(' '):
            value = 1.28 if last.isdigit() else 1.50
        elif not previous:
            value = 2.03
        elif last.isdigit():
            value = 1.39
        elif last.islower():
            value = 1.87 if '/' in previous else 1.75
        elif last.isupper():
            value = 1.67
        else:
            value = 1.70
    elif any(mark in s for mark in ('</', '/*', '#!')):
        value = 0.0
    elif '*/' in s:
        value = 0.22 if '\n' in s else 0.50
    elif '//' in s:
        value = 0.0
    elif clean.startswith('/') and clean[1:].isalpha():
        word = clean[1:]
        if len(word) == 1:
            value = 0.20 if word.isupper() else 0.03
        else:
            value = -0.18 if len(word) >= 3 else -0.12
    elif any(c.isalnum() for c in s):
        value = 0.0
    elif clean == '/':
        value = 0.32 if s.count('\n') > 1 else 0.86
    elif clean.endswith('/('):
        value = 0.83
    elif clean.endswith('/'):
        if '"' in s or "'" in s or '`' in s:
            value = 1.20
        elif '_' in s:
            value = 1.76
        elif '\\' in s:
            value = 0.95
        else:
            value = 1.35
    elif clean.startswith('/'):
        value = 0.0
    else:
        value = 0.65 if '"' in s or "'" in s else 0.0
    return None, value

