"""Predict strong activations for path slashes and mathematical division marks."""

READS = ()


def step(carry, prefix, upstream):
    piece = prefix.token_strings[-1]

    # A slash opening a parenthesized divisor is a separate, weaker cue.
    if "/(" in piece:
        return None, 0.9

    clean = piece.rstrip()
    if not clean.endswith("/"):
        return None, 0.0
    before = clean[:-1]

    # Do not treat word-internal slashes or closing markup/comments as separators.
    if any(ch.isalnum() for ch in before) or before.endswith(("/", "<", "*")):
        return None, 0.0
    if piece.endswith("\n"):
        return None, 0.75
    if clean.strip() == "/":
        return None, 1.6
    return None, 1.5

"""Predict a small negative response for sibilant/affricate spellings.
This catches several Cyrillic, accented Latin, Arabic, and Thai letters;
other token pieces are left at zero.
"""
READS = ()

SIBILANT_AFFRICATE_LETTERS = frozenset(
    "чЧщЩцЦшШжЖзЗčČšŠžŽçÇćĆĉĈچช"
)


def step(carry, prefix, upstream):
    token = prefix.token_strings[-1]
    if any(letter in SIBILANT_AFFRICATE_LETTERS for letter in token):
        return None, -0.6
    return None, 0.0

programs.sol:
"""Predict a local spelling signal after a token ending in p, п, or π.

Same-script continuations get a signed score from their initial letter,
length, and vowel/liquid clusters. Short pr-like spellings are strongest;
i-like fragments are weaker or negative. A separate 'to' rule captures
'up to'. Word breaks and mixed-case initial capitals otherwise get zero.

Only the preceding token is retained, resetting at document changes.
This deliberately leaves weak background and finer lexical variation out.
"""
import unicodedata

READS = ()
INITIAL = (
    ('aаuу', 0.35),
    ('oо', 0.50),
    ('eе', 0.05),
    ('iи', -0.20),
    ('lл', 0.40),
    ('rр', 1.65),
    ('ы', 0.80),
    ('s', 0.15),
    ('w', 0.50),
)


def _score(previous, text):
    p = previous.lower()
    if not p.endswith(('p', 'п', 'π')):
        return 0.0
    if text in (' to', '-to') and p.endswith('p'):
        return 2.0 if p.strip() == 'up' else 0.25
    if not text or not text[0].isalpha():
        return 0.0
    if text[0].isupper() and not text.isupper():
        return 0.0
    s = ''.join(c for c in unicodedata.normalize('NFD', text.lower())
                if not unicodedata.combining(c))
    first, n = s[0], len(s)
    if first not in 'abcdefghijklmnopqrstuvwxyzаеиоулрыαειολρ':
        return 0.0
    # A Greek variable followed by a Latin identifier is not a p-word.
    if p.endswith('π'):
        if first == 'ρ':
            return 1.5
        if first == 'ο':
            return 1.4 if n == 1 else 0.7
        if first == 'α':
            return 0.7
        return 0.4 if first in 'ελ' else 0.0
    if p.endswith('п') and not ('а' <= first <= 'я'):
        return 0.0
    if p.endswith('p') and not ('a' <= first <= 'z'):
        return 0.0
    if s == 'ro':
        return 2.9 if p.endswith('pp') else 5.1
    if s == 'ро':
        return 3.4
    score = -0.15 + sum(w for letters, w in INITIAL if first in letters)
    score += 0.50 if n == 1 else 0.25 if n == 2 else 0.0
    if first in 'rр':
        score += 0.30 if n <= 3 else -0.40 if n >= 5 else 0.0
        if s.startswith('ro'):
            score += 0.85
        if s.startswith('ra'):
            score -= 0.70
        if first == 'р' and n <= 3:
            score += 0.50
        if text[0].lower() == 'ř':
            score += 1.0
    elif n > 1 and first in 'aeouаеоу':
        if s[1] in 'rlрл':
            score += 0.40
        elif s[1] in 'szсз':
            score += 0.50
    if len(p) > 1:
        if p[-2] in 'eoео':
            score += 0.20
        elif not p[-2].isalnum() and not p[-2].isspace():
            score += 0.35
    return score


def step(carry, prefix, upstream):
    doc, text = prefix.document_ids[-1], prefix.token_strings[-1]
    prev = carry[1] if carry is not None and carry[0] == doc else ''
    return (doc, text), float(_score(prev, text))

"""A lexical early-time/order detector, with short temporal phrase rules.

Training examples concentrate large negative activations on early/earlier/
earliest, with smaller responses to beginnings, youth, before/first, and
related time words. The word classes below approximate this pattern; they
include a few translations and recognizable word stems. Outside these word
classes and phrases, the prediction is zero.
The previous two tokens allow phrases such as prior to and beginning of.
State resets at document boundaries. No model internals or token-ID table
are used; residual variation outside these concepts is not modeled.
"""
READS = ()

ORDER = {'first', 'before', 'late', 'soon', 'sooner'}
PAST = {'prior', 'previous', 'previously', 'later', 'originally', 'beforehand'}
BEGIN = {'begin', 'begins', 'began', 'prefix', 'beginners'}
YOUTH = {'young', 'childhood', 'jeune', '童年'}
HASTE = {'quickly', 'rapidly', 'swiftly', 'shortly', 'speedy'}


def lexical_value(token, word):
    if word == 'early':
        value = -8.6 if token != 'early' else -5.8
    elif word == 'earlier':
        value = -4.15 if token[0].isspace() else -3.4
    elif word == 'earliest':
        value = -5.0
    elif word in ORDER:
        value = -0.95
        if not token[:1].isspace() and word == 'late':
            value = -0.3
    elif word in PAST:
        value = -0.8 if token[:1].isspace() else -0.5
    elif word in BEGIN or word in HASTE or word in {'younger', 'youngest', 'youth'}:
        value = -0.65
        if token == 'begin':
            value = -0.2
    elif word in YOUTH:
        value = -1.6 if not token.strip().istitle() else -1.2
    elif word in {'ancient', 'preceding'}:
        value = -1.4
    elif word == 'beginning':
        value = -1.2 if token.strip().islower() else -0.9
    elif word == 'beginnings':
        value = -2.4
    elif word == 'ago':
        value = -1.15 if token[:1].isspace() else -0.3
    elif word in {'morning', 'mornings'}:
        value = -0.85
    elif word in {'origin', 'origins', 'start', 'small', 'roots', 'older'}:
        value = -0.3
    elif word in {'dawn', 'onset', 'pioneer', 'embry', 'embryo', 'premature'}:
        value = -0.8
    elif word in {'oldest', 'preliminary', 'precursor', 'firstly'}:
        value = -0.6
    elif word == '早':  # Chinese: early
        value = -4.55
    elif word in {'ран', 'frü'}:  # Russian/German early-time stems
        value = -2.6 if token[:1].isspace() else 0.0
    elif word in {'最早', '最早的'}:  # earliest
        value = -4.1
    elif word in {'提前', '初期', '早在', '清晨', '早点'}:  # early time
        value = -2.3
    elif word in {'最初', '早上', '早已'}:  # initially, morning, already
        value = -1.4
    elif word in {'以前', '之前', '古', '幼', '青年', '年轻', '年輕'}:
        value = -0.75  # before, ancient, or young
    elif word in {'第一', '首先', '先', '初', '开始'}:  # first or beginning
        value = -0.45
    elif word in {'начал', 'bereits'} and token[:1].isspace():
        value = -1.1  # began (Russian), already (German)
    elif word in {'перв', 'молод', 'древ', 'ersten', 'jeunes'}:
        value = -0.75 if token[:1].isspace() else 0.0
    else:
        value = 0.0
    return value


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    if carry is None or carry[0] != doc:
        prev = older = ''
    else:
        _, prev, older = carry
    token = prefix.token_strings[-1]
    word = token.strip(' \t\r\n._').lower()
    value = lexical_value(token, word)

    # A definite or intensified beginning is more emphatic.
    if prev in {'the', 'very'}:
        if word == 'early':
            value -= 0.95
        elif word == 'earlier':
            value -= 0.5
        elif word == 'earliest':
            value -= 0.8
        elif word == 'beginning':
            value -= 0.75

    # Connectors belonging to an order/beginning phrase.
    if word == 'of':
        if prev in {'beginning', 'beginnings', 'origins'}:
            value = -2.4 if prev != 'beginnings' else -3.2
        elif prev in {'start', 'onset', 'birth', 'dawn'}:
            value = -1.5
        elif prev in {'origin', 'roots', 'first'}:
            value = -1.05
        elif prev in {'stages', 'youth', 'age', 'history', 'development'}:
            value = -0.5
    elif word == 'to':
        if prev == 'prior':
            value = -1.85
        elif prev in {'begin', 'begins', 'beginning'}:
            value = -1.6
        elif prev == 'began':
            value = -1.1
        elif prev in {'start', 'starts', 'started', 'starting'}:
            value = -0.55

    # Early + a time noun or connector: early days, early in, etc.
    if prev in {'early', 'earlier', 'earliest'}:
        scale = 0.5 if prev == 'earlier' else 1.0
        if word == 'on':
            value = -5.2 * scale
        elif word == 'in':
            value = -2.8 * scale
        elif word in {'days', 'year', 'years', 'morning', 'mornings'}:
            value -= 3.0 * scale
        elif word == 'childhood':
            value -= 3.8 * scale
        elif word in {'life', 'age', 'ages', 'stage', 'stages', 'part'}:
            value -= 1.8 * scale
        elif word in {'as', 'than', 'this'}:
            value = -0.8 * scale
    if older in {'early', 'earliest'} and word == 'of':
        value -= 0.7
    return (doc, word, prev), float(value)

