"""Mark words that place events in time or order.

The strongest response is to “early”; the smaller responses are to
words such as “first”, “before”, “previous”, and “later”.
"""

READS = ()

ORDER_WORDS = frozenset({
    "first", "before", "previous", "prior", "preceding", "past",
    "late", "later", "quickly", "once", "early",
})


def step(carry, prefix, upstream):
    word = prefix.token_strings[-1].strip().lower().strip(".,!?;:()[]{}\"'“”‘’")
    if word == "early":
        return None, -9.3
    if word in ORDER_WORDS:
