programs.sol:
"""Record IDs and names of record/form fields.

The main response is to ID suffixes and properties. Contact information,
personal names and translated field labels also respond, especially inside
identifiers or form-element selectors. Ordinary prose is mostly left at zero.
Access operations and infrastructure names get small negative values.
The state remembers only the previous token and recent code punctuation.
"""
READS = ()

LOCATION_FIELDS = set('lat lng latitude longitude district '
                      'postcode zipcode'.split())
PERSON_NAMES = set('firstname lastname fullname surname fname lname'.split())
CONTACT = set('email username password phone mobile telephone address'.split())
LABELS = set('name description detail details date month total '
             'status code title'.split())
ENTITIES = set('customer employee merchant supplier patient student '
               'product order item'.split())
TRANSLATED = set('nombre apellido telefono correo direccion usuario cliente nome '
                 'descricao descripcion detalle detalhe pedido codigo fecha'.split())
FORM_ALIASES = set('fname lname addr lat lng pass'.split())
OPERATIONS = set('get set put remove delete clear getattribute getparameter'.split())
INFRASTRUCTURE = set('repository builder listener iterator model '
                     'request button form'.split())


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    if carry is None or carry[0] != doc:
        previous, recent = '', ()
    else:
        previous, recent = carry[1:]
    token = prefix.token_strings[-1]
    current = token.strip()
    word = current.lstrip('._(/\\\"\'-$').lower()
    spaced = token[:1].isspace()
    letter = bool(previous) and previous[-1].isalpha()
    quoted = previous.rstrip().endswith(('"', "'", '`'))
    member = current.startswith(('.', '_'))
    selector = previous.rstrip().endswith('#')
    code = sum(recent) >= 2
    marker = any(c in token for c in '{};=_') or current.startswith('.')
    carry = (doc, token, (recent + (int(marker),))[-12:])

    if word == 'id':
        if current == '.id' and previous.lstrip('( ') == 'R':
            value = 0.98  # Android resource IDs: R.id
        elif current.startswith('.'):
            value = 0.70 if current == '.id' else 0.50
        elif current.startswith('_'):
            value = 0.65 if current.endswith('ID') else 0.50
        elif spaced or current not in {'id', 'ID', 'Id'}:
            value = 0.33
        elif current == 'Id':
            value = 0.46 if letter or quoted else 0.26
        elif current == 'ID':
            if quoted:
                value = 0.60
            elif letter and not previous[-1].isupper():
                value = 0.55
            else:
                value = 0.15
        else:
            if quoted:
                value = 0.65
            elif not letter:
                value = 0.56
            else:
                value = 0.33 if code else 0.08
        return carry, value
    if (len(current) > 2 and current.endswith(('Id', 'ID'))
            and current[-3].islower()):
        return carry, 0.40
    if word in {'uid', 'pk', 'fk', 'cid'}:
        return carry, 0.30 if member or spaced else 0.12
    if word == 'seq' and member:
        return carry, 0.40
    if word in {'ids', 'no'} and member:
        return carry, 0.27
    if current == 'No' and letter and code:
        return carry, 0.40
    if word in LOCATION_FIELDS and member:
        return carry, 0.30

    if selector and word in (PERSON_NAMES | CONTACT | LABELS | FORM_ALIASES):
        return carry, 0.95 if word in {'fname', 'lname'} else 0.75
    if word in TRANSLATED:
        base = 0.65
    elif word in PERSON_NAMES:
        base = 0.45
    elif word in CONTACT:
        base = 0.30
    elif word in LABELS:
        base = 0.20
    elif word in ENTITIES:
        base = 0.15
    else:
        # Compound field labels, e.g. ProductName or getEmail.
        for ending in ('Name', 'Email', 'Address'):
            if current.endswith(ending) and current != ending:
                root = current[:-len(ending)].lower()
                entity = any(root.endswith(e) for e in ENTITIES)
                return carry, 0.45 if entity else 0.20
        if not spaced and word in OPERATIONS:
            return carry, -0.12 if member else -0.06
        if not spaced and word in INFRASTRUCTURE:
            return carry, -0.14
        return carry, 0.0

    if member or (letter and not spaced and current[:1].isupper()):
        return carry, base
    if quoted and not spaced:
        return carry, 0.05 if word == 'name' else base
    if spaced:
        return carry, 0.03 if letter else base * 0.3
    return carry, base * 0.4

"""A local lexical predictor, especially for return and words after @.

It also recognizes the next word after size modifiers, East Asian size
fragments 大/小/巨/대, and Japanese お/ご (often honorific prefixes).
Whole and split-token spellings receive different strengths. Small syntax
signals cover attributes, double underscores, URL hosts, imports, model
delimiters and size-of operators.
The numbers approximate training averages for these cue classes.
The previous token is forgotten at document boundaries.
"""
READS = ()

RETURN = {'return', 'returns', 'returned', 'returning'}
SIZE = {
    'big', 'bigger', 'biggest', 'large', 'larger', 'largest',
    'small', 'smaller', 'smallest', 'little', 'great', 'greater',
    'greatest', 'grand', 'major', 'huge', 'macro',
}
FUNCTION_WORDS = {
    'a', 'an', 'the', 'and', 'or', 'but', 'that', 'in', 'for',
    'with', 'on', 'is', 'are', 'was', 'be', 'by', 'at', 'it',
    'this', 'which',
}
QUANTITY = {'amount', 'number', 'proportion', 'size', 'scale', 'bit'}
# (One-character continuation, longer continuation).
EAST_ASIAN_PREFIXES = {
    '大': (1.88, 0.86), '小': (1.20, 0.67), '巨': (0.56, 0.28),
    '대': (1.74, 0.73), 'お': (1.73, 1.20), 'ご': (0.55, 0.22),
}


def activation(s, previous):
    word = s.strip()
    lower = word.lower()
    before = previous.strip()
    prev = before.lower()
    if previous.rstrip().endswith('@'):
        if s[:1].isspace():
            return 0.62
        if word[:1].isdigit():
            return 0.90
        if not word[:1].isalpha():
            return 0.66
        if lower in {'param', 'parameter', 'arg', 'args'}:
            return 1.16
        if lower in {'return', 'returns', 'type', 'var', 'method'}:
            return 3.28
        if lower in {'see', 'link', 'linkplain', 'example', 'throws'}:
            return 2.24
        if lower in {'typescript', 'types', 'angular'}:
            return 4.26
        if previous.endswith(('"@', "'@")) and len(before) == 2:
            return 3.06
        if lower in {'exception', 'dev', 'php', 'phpstan', 'this'}:
            return 4.0
        return 1.69 if word[:1].isupper() else 1.80

    if lower in RETURN:
        if lower == 'return':
            return 0.94 if s.startswith('\t') else 0.82
        return 0.65 if lower == 'returning' else 0.71
    if word.startswith('@') and word[1:2].isalpha():
        return 0.63 if word[1:2].isupper() else 0.19

    if not s[:1].isspace() and (word[:1].isalpha() or word[:1] == '\ufffd'):
        if before[-1:] in EAST_ASIAN_PREFIXES:
            single, multiple = EAST_ASIAN_PREFIXES[before[-1]]
            return single if len(word) == 1 else multiple

    if prev in SIZE and word[:1].isalpha():
        small = prev in {'small', 'smaller', 'smallest', 'little'}
        if lower in {'to', 'of', 'as', 'than', 'enough'}:
            return -0.24
        if lower in FUNCTION_WORDS:
            return 0.11
        if lower in QUANTITY:
            return -0.60 if small else -0.11
        if word[:1].isupper() or before[:1].isupper():
            return 0.62
        if small or prev in {'great', 'greater', 'greatest'}:
            return 0.26
        return 0.55 if prev in {'major', 'biggest', 'macro'} else 0.49

    if word[:1].isalpha() and not s[:1].isspace():
        if previous.endswith('#['):
            return 1.08
        if previous.endswith('__') and len(previous) < 5:
            return 0.12 if previous == '__' else 0.47
        if previous.endswith('://') and lower != 'www':
            return 0.42
    if prev == 'import' and word[:1].isalpha():
        return 0.09
    if lower in {'sizeof', '(sizeof'}:
        return -0.68
    if s in {'<think>', '</tool_call>'}:
        return 0.14
    return 0.0015


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    s = prefix.token_strings[-1]
    previous = carry[1] if carry is not None and carry[0] == doc else ''
    return (doc, s), float(activation(s, previous))

programs.luna:
"""Recognize the recurring English return/returned/returns word family.

In the inspected high-impact examples, this word family recurs across code
and prose. The rest of the time this rare component is left silent.
"""
READS = ()
RETURN_WORDS = {"return", "returns", "returned", "returning"}

def step(carry, prefix, upstream):
    word = prefix.token_strings[-1].strip().lower()
    value = 0.8 if word in RETURN_WORDS else 0.0
    return None, float(value)
